window.AULAS["farma-gilmar-01"] = {"subtitulo": "Introdução: vocabulário, formas farmacêuticas, áreas e nomenclatura", "pdf": "pdf/gilmar/aula-01.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 1 · Fármaco (Prof. Dr. Gilmar S. Erzinger)", "Brunton e Knollmann (Goodman & Gilman); Katzung (Farmacologia Básica e Clínica); OMS (Guide to Good Prescribing), citados nos slides"], "tabela": {"titulo": "Radicais da DCB: o nome revela a classe (slide 9)", "colunas": ["Radical", "Classe", "Exemplos"], "linhas": [["-olol", "Betabloqueadores", "propranolol, atenolol, metoprolol"], ["-pril", "Inibidores da ECA", "captopril, enalapril, ramipril"], ["-sartana", "Bloqueadores do receptor AT1", "losartana, valsartana, olmesartana"], ["-statina", "Inibidores da HMG-CoA redutase", "sinvastatina, atorvastatina, rosuvastatina"], ["-prazol", "Inibidores da bomba de prótons", "omeprazol, pantoprazol, esomeprazol"], ["-azepam / -azolam", "Benzodiazepínicos", "diazepam, clonazepam, midazolam"], ["-gliflozina", "Inibidores do SGLT2", "dapagliflozina, empagliflozina"], ["-mabe", "Anticorpos monoclonais", "rituximabe, adalimumabe, pembrolizumabe"]]}, "resumo": [{"titulo": "1. Vocabulário básico", "pontos": [{"t": "Fármaco × medicamento × droga × remédio", "sub": ["Fármaco: substância química de estrutura definida com efeito farmacológico, o princípio ativo, como a amoxicilina (slide 2).", "Medicamento: produto farmacêutico tecnicamente elaborado com finalidade profilática, curativa, paliativa ou diagnóstica; é fármaco + excipientes + forma farmacêutica (slide 2).", "Droga: termo amplo para qualquer substância que altera funções do organismo; no uso leigo, associa-se a substâncias de abuso (slide 2).", "Remédio: tudo o que alivia ou cura, incluindo medidas não farmacológicas, como repouso, fisioterapia e dieta (slide 2)."]}, {"t": "Placebo e nocebo", "sub": ["Placebo: preparação sem ativo farmacológico específico; o efeito placebo é real e interfere em ensaios clínicos (slide 2).", "Nocebo: efeito adverso sem causa farmacológica, que também precisa ser controlado nos ensaios (slide 2; complementa Goodman & Gilman)."]}]}, {"titulo": "2. Formas farmacêuticas", "pontos": [{"t": "Por que existem", "sub": ["As formas garantem precisão de dose, estabilidade, transporte, segurança e otimização do efeito (slide 3)."]}, {"t": "Sólidas", "sub": ["Comprimidos: podem ser efervescentes, sublinguais ou revestidos.", "Cápsulas: invólucro, geralmente de gelatina, com ativo sólido ou líquido.", "Drágeas: revestidas com açúcar e outras substâncias para mascarar sabor ou proteger o ativo no estômago.", "Supositórios e óvulos: derretem na temperatura corporal, para uso retal ou vaginal (slide 4)."]}, {"t": "Semissólidas", "sub": ["Pomadas: mais gordurosas e oclusivas. Cremes: emulsões óleo-água, menos oleosas. Géis: base aquosa com agente que confere consistência (slide 5)."]}, {"t": "Líquidas", "sub": ["Soluções: fármaco totalmente dissolvido. Suspensões: partículas sólidas dispersas, exigem agitação. Xaropes e elixires: alta concentração de açúcar ou adoçantes (slide 6).", "Boa opção para crianças e idosos com dificuldade de deglutição (slide 6)."]}, {"t": "Gasosas", "sub": ["Aerossóis, sprays e inalantes atingem diretamente as vias respiratórias (slide 7)."]}]}, {"titulo": "3. Áreas da farmacologia", "pontos": [{"t": "Farmacocinética (ADME)", "sub": ["O que o organismo faz com o fármaco: absorção, distribuição, metabolismo e excreção (slide 8)."]}, {"t": "Farmacodinâmica", "sub": ["O que o fármaco faz com o organismo: alvos, mecanismos de ação e relação dose-efeito (slide 8)."]}, {"t": "Farmacoterapia e farmacovigilância", "sub": ["Farmacoterapia: escolha, dose, via, duração e monitoramento. Farmacovigilância: detecção e prevenção de reações adversas após a comercialização (slide 8).", "Transversais: toxicologia, farmacogenética e farmacoepidemiologia (slide 8)."]}]}, {"titulo": "4. Nomenclatura DCB", "pontos": [{"t": "Radicais revelam a classe", "sub": ["-olol: betabloqueadores; -pril: inibidores da ECA; -sartana: bloqueadores AT1; -statina: inibidores da HMG-CoA redutase; -prazol: inibidores da bomba de prótons; -azepam e -azolam: benzodiazepínicos; -gliflozina: inibidores do SGLT2; -mabe: anticorpos monoclonais (slide 9).", "Atenção: nem todo nome parecido indica a mesma classe; confirmar sempre (slide 9)."]}, {"t": "Fontes oficiais de nome e classe", "sub": ["DCB (Denominação Comum Brasileira), que segue os radicais da DCI/OMS; Bulário Eletrônico da Anvisa (slides 9 e 11)."]}]}, {"titulo": "5. Raciocínio terapêutico", "pontos": [{"t": "Descrição de um medicamento", "sub": ["1 classe e mecanismo; 2 farmacocinética (via, biodisponibilidade, t½, metabolismo CYP, eliminação renal); 3 usos clínicos; 4 segurança (RAM, contraindicações, gestação); 5 interações e monitoramento (slide 10)."]}, {"t": "Guia para a Boa Prescrição (OMS, 1994)", "sub": ["Definir o problema; objetivo terapêutico; escolher o tratamento; prescrever; informar o paciente; monitorar (slide 12)."]}, {"t": "Fontes", "sub": ["Goodman & Gilman; Katzung; Rang & Dale; UpToDate e Micromedex para ajuste de dose e interações (slide 11)."]}]}, {"titulo": "6. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Diferença entre fármaco e medicamento e quais são os excipientes.", "Qual forma farmacêutica usar em criança ou em quem não deglute.", "Classe pelo radical (estatina, sartana, prazol, olol) e o caso do enalapril."]}]}], "glossario": [{"termo": "Fármaco", "tecnica": "Vocabulário", "definicao": "Substância química de estrutura definida, com efeito farmacológico; o princípio ativo.", "slide": 2}, {"termo": "Medicamento", "tecnica": "Vocabulário", "definicao": "Produto farmacêutico elaborado, com fármaco, excipientes e forma farmacêutica.", "slide": 2}, {"termo": "Nocebo", "tecnica": "Vocabulário", "definicao": "Efeito negativo que ocorre sem ação do princípio ativo, real e que interfere nos ensaios.", "slide": 2}, {"termo": "Drágea", "tecnica": "Forma sólida", "definicao": "Comprimido com revestimento de açúcar e outras substâncias, para mascarar sabor ou proteger o ativo no estômago.", "slide": 4}, {"termo": "DCB", "tecnica": "Nomenclatura", "definicao": "Denominação Comum Brasileira, baseada nos radicais da DCI/OMS.", "slide": 9}, {"termo": "Farmacovigilância", "tecnica": "Área da farmacologia", "definicao": "Detecção, avaliação e prevenção de reações adversas após a comercialização.", "slide": 8}], "caso": {"titulo": "Caso: tosse após início de enalapril", "perfil": "Radical do nome, mecanismo da tosse e classe alternativa.", "etapas": [{"titulo": "Etapa 1: classe e mecanismo", "texto": "Mulher de 58 anos, hipertensa e diabética, em uso de enalapril 20 mg a cada 12 h. Refere tosse seca persistente há dois meses, sem febre; a radiografia de tórax é normal.", "perguntas": [{"pergunta": "Qual é a classe do fármaco, pelo radical do nome?", "alts": ["Inibidor da enzima conversora de angiotensina (ECA)", "Bloqueador do receptor AT1 da angiotensina", "Betabloqueador não seletivo", "Inibidor da HMG-CoA redutase", "Inibidor da bomba de prótons"], "erradas": ["Bloqueador AT1 tem radical -sartana, como losartana.", "Betabloqueadores têm radical -olol.", "Estatinas têm radical -statina.", "Inibidores da bomba de prótons têm radical -prazol."], "justificativa": "O radical -pril identifica os inibidores da ECA, como captopril, enalapril e ramipril (slide 9)."}]}, {"titulo": "Etapa 2: alternativa sem tosse", "texto": "A tosse é atribuída ao acúmulo de bradicinina. O médico quer manter o benefício renal e cardiovascular, sem a tosse.", "perguntas": [{"pergunta": "Qual classe alternativa mantém o benefício e não causa tosse, segundo a aula?", "alts": ["Bloqueador do receptor AT1, de radical -sartana", "Betabloqueador de radical -olol, sem efeito renal", "Inibidor da bomba de prótons, de radical -prazol", "Benzodiazepínico, de radical -azepam", "Inibidor do SGLT2, de radical -gliflozina"], "erradas": ["Betabloqueadores não são alternativa renal a IECA neste caso.", "Inibidor da bomba de prótons não trata a pressão arterial.", "Benzodiazepínicos não têm efeito renal ou anti-hipertensivo.", "Inibidores do SGLT2 não são a alternativa citada na aula."], "justificativa": "Bloqueadores AT1 (-sartana) atuam na mesma via sem acumular bradicinina, e a aula cita a tosse como efeito da classe anterior (slide 14)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um xarope de amoxicilina é descrito como medicamento, e não como fármaco. Qual componente o torna medicamento, segundo a aula?", "alternativas": ["Apenas a finalidade curativa, sem excipientes", "Apenas a embalagem e a bula, sem o princípio ativo", "Excipientes e forma, além do princípio ativo", "Somente a DCB, que define o produto farmacêutico", "A dose máxima diária, que define o medicamento"], "gabarito": "C", "justificativa": "Medicamento é o produto farmacêutico com fármaco, excipientes e forma farmacêutica (Aula 1, slide 2).", "tecnica": "Vocabulário", "slide": 2, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um paciente diz que tomou um 'remédio' e não um medicamento. Qual conceito da aula inclui medidas não farmacológicas, como repouso e fisioterapia?", "alternativas": ["Medicamento, produto farmacêutico com ativo e forma definida", "Droga, qualquer substância que altera funções do organismo", "Fármaco, substância química com efeito farmacológico definido", "Remédio, incluindo medidas não farmacológicas", "Placebo, preparação sem ativo farmacológico específico"], "gabarito": "D", "justificativa": "Remédio é tudo o que alivia ou cura, inclusive medidas não farmacológicas (Aula 1, slide 2).", "tecnica": "Vocabulário", "slide": 2, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Em um estudo com placebo, o grupo controle melhora de forma relevante. Qual fenômeno a aula cita para esse resultado e por que ele importa para o ensaio?", "alternativas": ["Efeito farmacológico do excipiente, que o ensaio deve corrigir", "Erro de dose, que o ensaio deve ignorar por randomização", "Efeito placebo, que é real", "Farmacovigilância, que mede eventos após a comercialização", "Biodisponibilidade, que altera a concentração plasmática do placebo"], "gabarito": "C", "justificativa": "A aula cita o efeito placebo, que é real e interfere em ensaios (Aula 1, slide 2).", "tecnica": "Placebo", "slide": 2, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um comprimido sublingual e um comprimido revestido de açúcar podem ser da mesma substância. Qual é o propósito do revestimento de açúcar, segundo a aula?", "alternativas": ["Acelerar a absorção no intestino delgado", "Mascarar o sabor ou proteger o ativo no estômago", "Aumentar a concentração do fármaco na forma sólida", "Permitir uso retal ou vaginal", "Dispersar partículas sólidas, exigindo agitação"], "gabarito": "B", "justificativa": "Drágeas são revestidas para mascarar sabor ou proteger o ativo no estômago (Aula 1, slide 4).", "tecnica": "Formas sólidas", "slide": 4, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um frasco de suspensão precisa de agitação antes de cada uso. Qual característica da forma farmacêutica explica essa exigência?", "alternativas": ["Fármaco totalmente dissolvido, sem tendência a sedimentar", "Emulsão de óleo e água, que se separa em repouso", "Base gordurosa de consistência semissólida", "Partículas sólidas dispersas", "Gás dissolvido, que escapa ao abrir o frasco"], "gabarito": "D", "justificativa": "Suspensões têm partículas sólidas dispersas e exigem agitação (Aula 1, slide 6).", "tecnica": "Formas líquidas", "slide": 6, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Para uma lesão cutânea que precisa de efeito local e menos oleosidade, qual forma semissólida a aula indica, e qual a base?", "alternativas": ["Creme, emulsão menos oleosa", "Pomada, uma base gordurosa e oclusiva", "Gel de base oleosa, de consistência firme", "Supositório, que derrete na pele", "Aerossol, que atinge a mucosa respiratória"], "gabarito": "A", "justificativa": "Cremes são emulsões de fácil espalhabilidade, menos oleosas que as pomadas (Aula 1, slide 5).", "tecnica": "Formas semissólidas", "slide": 5, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um paciente com dificuldade de deglutição precisa de forma que atinja rapidamente a circulação. Qual forma a aula cita para esse caso?", "alternativas": ["Sólida, como comprimido revestido de longa liberação", "Gasosa, como inalante de uso oral", "Líquida, como solução, que é de rápida absorção", "Semissólida, como pomada oclusiva", "Supositório, que tem absorção lenta por via oral"], "gabarito": "C", "justificativa": "Formas líquidas são ideais para absorção rápida ou pacientes com dificuldade de deglutição (Aula 1, slide 6).", "tecnica": "Formas líquidas", "slide": 6, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um laboratório estuda a absorção e a eliminação de um fármaco novo. Qual área da farmacologia a aula associa a essa investigação?", "alternativas": ["Farmacocinética, que descreve ADME", "Farmacodinâmica, que descreve alvos e mecanismos", "Farmacoterapia, que descreve a escolha clínica", "Farmacovigilância, que detecta reações após comercialização", "Farmacologia de populações, que descreve a dose ideal"], "gabarito": "A", "justificativa": "Farmacocinética é o que o organismo faz com o fármaco: ADME (Aula 1, slide 8).", "tecnica": "Áreas da farmacologia", "slide": 8, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um fármaco é descrito como tendo efeito adverso raro, detectado após milhares de pacientes. Qual área é responsável por esse monitoramento, e qual é o nome da notificação no Brasil?", "alternativas": ["Farmacocinética; notificação pela bula", "Farmacovigilância; notificação pelo VigiMed", "Farmacodinâmica; notificação pela DCB", "Farmacoterapia; notificação pelo Bulário", "Farmacologia básica; notificação pelo RENAME"], "gabarito": "B", "justificativa": "Farmacovigilância detecta e avalia reações após a comercialização (Aula 1, slide 8); a notificação é pelo VigiMed (citado na aula 3, slide 27).", "tecnica": "Farmacovigilância", "slide": 8, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um fármaco novo é apresentado com radical '-statina'. Qual classe é esperada e qual é o alvo molecular, segundo a aula?", "alternativas": ["Inibidores da bomba de prótons", "Bloqueadores do receptor AT1", "Betabloqueadores não seletivos", "Inibidores da HMG-CoA redutase", "Benzodiazepínicos de ação curta"], "gabarito": "D", "justificativa": "O radical -statina identifica os inibidores da HMG-CoA redutase (Aula 1, slide 9).", "tecnica": "Nomenclatura DCB", "slide": 9, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um fármaco com radical '-prazol' é usado no refluxo. Qual é a classe, e qual alvo ele inibe?", "alternativas": ["Inibidor da HMG-CoA redutase, da síntese de colesterol", "Bloqueador do receptor AT1, da angiotensina II", "Inibidor da ECA, da bradicinina", "Betabloqueador, do receptor adrenérgico beta-1", "Inibidor da bomba de prótons, da H+/K+-ATPase"], "gabarito": "E", "justificativa": "O radical -prazol identifica os inibidores da bomba de prótons (Aula 1, slide 9).", "tecnica": "Nomenclatura DCB", "slide": 9, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um paciente usa losartana e outro usa enalapril. A tosse seca surge em um, e não no outro. Qual explicação mecanística a aula dá, e qual é a classe de cada um?", "alternativas": ["Enalapril é bloqueador AT1 (-sartana); losartana é IECA, que aumenta bradicinina", "Enalapril, IECA, aumenta bradicinina; losartana é -sartana", "Ambos são IECA, mas a losartana tem mais tosse por ser lipofílica", "Ambos são bloqueadores AT1, sem diferença de mecanismo", "Enalapril é betabloqueador (-olol), e losartana é estatina (-statina)"], "gabarito": "B", "justificativa": "A pista da aula é a bradicinina, acumulada pela inibição da ECA (-pril); o bloqueador AT1 (-sartana) não causa essa via (Aula 1, slides 9 e 14).", "tecnica": "Caso clínico: IECA", "slide": 14, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Ao descrever um medicamento, o raciocínio clínico começa pela classe e mecanismo. Qual item vem imediatamente depois, e o que ele deve conter?", "alternativas": ["Farmacocinética, com via e biodisponibilidade", "Usos clínicos, com indicações e diretrizes", "Segurança, com RAM e contraindicações", "Interações, com níveis e exames", "Mecanismo molecular, com alvo e efeito fisiológico"], "gabarito": "A", "justificativa": "A estrutura da aula é classe e mecanismo, farmacocinética, usos, segurança e interações (Aula 1, slide 10).", "tecnica": "Estrutura de descrição", "slide": 10, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Segundo a OMS, o raciocínio terapêutico começa pelo problema. Qual passo vem logo depois de definir o problema?", "alternativas": ["Prescrever, com dose, via e duração", "Informar o paciente sobre uso e sinais de alerta", "Monitorar resposta e decidir manter ou parar", "Escolher o tratamento, avaliando custo e conveniência", "Objetivo terapêutico, com o que se quer"], "gabarito": "E", "justificativa": "O Guia da OMS segue: definir o problema, objetivo terapêutico, escolher, prescrever, informar e monitorar (Aula 1, slide 12).", "tecnica": "Raciocínio terapêutico", "slide": 12, "pdf": "pdf/gilmar/aula-01.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um estudante quer comparar duas fontes para um fármaco. Qual combinação a aula recomenda como fonte confiável, e qual deve ser evitada?", "alternativas": ["Redes sociais com resumo curto; evitar livros-texto por serem antigos", "Propaganda da indústria como fonte principal; evitar a Anvisa por ser burocrática", "Materiais sem autoria e blogs; evitar PubMed por ser técnico demais", "Apenas a bula do fabricante; evitar qualquer livro-texto", "Goodman & Gilman, Katzung e bulário da Anvisa"], "gabarito": "E", "justificativa": "A aula recomenda livros-texto, bulário e diretrizes, e desaconselha propaganda, materiais sem autoria e redes sociais sem referência (Aula 1, slide 11).", "tecnica": "Fontes confiáveis", "slide": 11, "pdf": "pdf/gilmar/aula-01.pdf"}], "id": "farma-gilmar-01", "titulo": "Aula 1", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-02"] = {"subtitulo": "Farmacocinética: ADME, biodisponibilidade, metabolismo e doses", "pdf": "pdf/gilmar/aula-02.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 2 · Farmacocinética (Prof. Dr. Gilmar S. Erzinger)", "Katzung, Farmacologia Básica e Clínica; Goodman & Gilman; Rowland e Tozer; Lei 9.787/1999 (citados nos slides)"], "tabela": {"titulo": "Vias de administração e biodisponibilidade (slide 7)", "colunas": ["Via", "Biodisponibilidade", "Característica principal"], "linhas": [["Intravenosa", "100% (referência)", "Início imediato; controle preciso da dose"], ["Intramuscular", "75 a ≤100%", "Rápida em solução aquosa; veículo oleoso forma depósito"], ["Subcutânea", "75 a ≤100%", "Absorção mais lenta que a IM (ex.: insulina, heparina)"], ["Oral", "5 a <100%", "Mais conveniente; sujeita à primeira passagem"], ["Retal", "30 a <100%", "Primeira passagem parcial; útil com vômitos"], ["Transdérmica", "80 a ≤100%", "Absorção lenta e sustentada (ex.: adesivos)"]]}, "resumo": [{"titulo": "1. O caminho do fármaco (ADME)", "pontos": [{"t": "Etapas", "sub": ["Liberação (desintegração e dissolução da forma), absorção, distribuição, metabolismo e excreção (slide 3).", "Cada etapa pode limitar o efeito; o metabolismo é sobretudo hepático, gerando metabólitos mais polares (slide 3)."]}]}, {"titulo": "2. Absorção e pH", "pontos": [{"t": "Mecanismos de passagem", "sub": ["Difusão passiva (principal, depende de lipossolubilidade); difusão facilitada; transporte ativo (transportadores SLC, efluxo por glicoproteína-P); endocitose (slide 4)."]}, {"t": "Ionização", "sub": ["Só a forma não ionizada atravessa bem a membrana (slide 4).", "Ácidos fracos (ex.: AAS) ficam mais não ionizados em pH ácido; bases fracas, em pH alcalino (slide 4).", "Henderson-Hasselbalch: pKa − pH = log([não ionizada]/[ionizada]) para ácidos (slide 4)."]}]}, {"titulo": "3. Curva concentração × tempo", "pontos": [{"t": "Parâmetros", "sub": ["Cmáx: pico. Tmáx: tempo até o pico, que indica a velocidade de absorção. AUC: área sob a curva, exposição total (slide 5).", "Janela terapêutica: entre a concentração mínima efetiva e a tóxica (slide 5).", "Duração do efeito: tempo acima da concentração mínima efetiva (slide 5)."]}]}, {"titulo": "4. Biodisponibilidade e bioequivalência", "pontos": [{"t": "Conceito", "sub": ["Biodisponibilidade (F): velocidade e quantidade com que o princípio ativo chega à circulação (slides 6 e 8). IV é 100%, por definição (slide 8).", "F = AUC oral ÷ AUC IV, corrigido pela dose (slide 8)."]}, {"t": "Via e biodisponibilidade", "sub": ["IV 100%; IM 75 a ≤100%; SC 75 a ≤100% (absorção mais lenta que a IM); oral 5 a <100% (sujeita à primeira passagem); retal 30 a <100%; transdérmica 80 a ≤100% (slide 7; Katzung)."]}, {"t": "Primeira passagem", "sub": ["Metabolismo intestinal e hepático antes da circulação sistêmica (slide 8).", "Alta extração: nitroglicerina (use sublingual), propranolol, morfina e lidocaína (slide 8).", "Cirrose ou shunt portossistêmico reduz a primeira passagem e aumenta a exposição (slide 8)."]}, {"t": "Bioequivalência e genéricos", "sub": ["Mesma fórmula e quantidade de princípio ativo, biodisponibilidade equivalente (slide 9).", "Critério: velocidade e extensão dentro de 80% a 125% da referência (slide 9).", "Base legal: Lei 9.787/1999 (slide 8 e referência do slide 22). Referência: marca; genérico: DCB; similar: marca própria, com equivalência exigida hoje (slide 10)."]}]}, {"titulo": "5. Distribuição", "pontos": [{"t": "Volume de distribuição (Vd)", "sub": ["Vd = dose ÷ C0. É volume aparente, não anatômico (slide 11).", "Vd baixo: fármaco retido no plasma (varfarina). Vd alto: acúmulo tecidual (amiodarona, digoxina) (slide 11)."]}, {"t": "Ligação a proteínas", "sub": ["Albumina liga ácidos fracos; α1-glicoproteína ácida liga bases (slide 11).", "Só a fração livre é ativa e eliminada; hipoalbuminemia aumenta a fração livre (fenitoína, slide 11)."]}, {"t": "Barreiras", "sub": ["Hematoencefálica: junções firmes e glicoproteína-P; inflamação meníngea aumenta a passagem. Placentária: fármacos lipossolúveis atravessam (slide 11).", "Redistribuição: tiopental e propofol terminam o efeito por redistribuição, não por eliminação (slide 11)."]}]}, {"titulo": "6. Metabolismo e CYP450", "pontos": [{"t": "Fases", "sub": ["Fase I: oxidação (CYP450), redução e hidrólise; introduz ou expõe grupos polares; pode ativar pró-fármacos ou gerar metabólitos tóxicos (NAPQI do paracetamol) (slide 12).", "Fase II: conjugação (glicuronidação, sulfatação, acetilação, metilação, glutationa); gera compostos inativos e hidrossolúveis (slide 12).", "Acetiladores lentos: mais toxicidade de isoniazida e hidralazina. Neonatos: glicuronidação imatura, síndrome cinzenta com cloranfenicol (slide 12)."]}, {"t": "CYP450", "sub": ["Superfamília sobretudo hepática; seis enzimas respondem por cerca de 90% do metabolismo de fármacos, sendo a CYP3A4 e a CYP2D6 as mais importantes (slide 13).", "3A4 é a de maior número de substratos; 2D6, 2C9, 2C19 e 1A2 completam as relevantes (slide 12)."]}, {"t": "Indução e inibição", "sub": ["Indutores (rifampicina, carbamazepina, fenitoína, fenobarbital, erva-de-são-joão, tabagismo): ↓ concentração; início lento, dias a semanas (slide 14).", "Inibidores (claritromicina, cetoconazol, itraconazol, fluconazol, ritonavir, amiodarona, fluoxetina e paroxetina para 2D6, suco de toranja para 3A4): ↑ concentração; início rápido (slide 14).", "Exemplos: rifampicina + contraceptivo oral (falha); sinvastatina + claritromicina (miopatia) (slide 14)."]}]}, {"titulo": "7. Excreção", "pontos": [{"t": "Renal", "sub": ["Filtração glomerular: só a fração livre; depende da TFG e é base do ajuste em doença renal (slide 15).", "Secreção tubular ativa (OAT/OCT): probenecida inibe penicilinas (slide 15).", "Reabsorção passiva depende do pH urinário: alcalinizar acelera a eliminação de ácidos fracos (salicilatos, fenobarbital) (slide 15)."]}, {"t": "Outras vias", "sub": ["Biliar e fecal, com circulação êntero-hepática que prolonga a ação (estrogênios). Pulmonar, para anestésicos inalatórios e etanol. Leite materno, onde bases fracas se concentram (slide 15)."]}]}, {"titulo": "8. Parâmetros que orientam a dose", "pontos": [{"t": "Fórmulas", "sub": ["CL: volume depurado por tempo; dose de manutenção = CL × Css ÷ F (slide 16).", "t½ = 0,693 × Vd ÷ CL; define intervalo entre doses (slide 16).", "Vd: dose de ataque = Vd × C alvo ÷ F (slide 16)."]}, {"t": "Acúmulo", "sub": ["Após 1 t½: 50% da Css; 2 t½: 75%; 3 t½: 87,5%; 4 a 5 t½: 94 a 97%, equilíbrio clínico (slide 17).", "Meia-vida longa (amiodarona, digoxina) justifica dose de ataque para chegar mais cedo ao alvo (slide 17)."]}, {"t": "Ordem da cinética", "sub": ["Primeira ordem (linear): fração constante por tempo; a maioria dos fármacos (slide 18).", "Ordem zero (saturável): quantidade constante por tempo; etanol, fenitoína e salicilatos em doses altas; pequeno aumento de dose gera grande aumento de concentração (slide 18)."]}]}, {"titulo": "9. Populações especiais", "pontos": [{"t": "Idosos, neonatos, gestantes, renais, hepáticos e obesos", "sub": ["Idosos: ↓ TFG, ↓ albumina, ↑ gordura; comece baixo e vá devagar (slide 19).", "Neonatos: imaturidade renal e hepática; dose por peso ou superfície (slide 19).", "Gestação: ↑ Vd, ↑ TFG, ↑ atividade de algumas CYP; reavaliar doses, como lamotrigina (slide 19).", "Doença renal: ajustar aminoglicosídeos, vancomicina, metformina e enoxaparina (slide 19).", "Doença hepática: sem marcador simples; usar Child-Pugh (slide 19).", "Obesidade: lipofílicos têm ↑ Vd (slide 19)."]}]}, {"titulo": "10. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Por que dose oral e dose IV diferem (primeira passagem).", "Qual parâmetro define dose de ataque e qual define manutenção.", "Quais CYP e quais indutores/inibidores aparecem em interação clássica (varfarina e fluconazol: CYP2C9)."]}]}], "glossario": [{"termo": "Biodisponibilidade (F)", "tecnica": "Farmacocinética", "definicao": "Fração da dose que chega inalterada à circulação sistêmica.", "slide": 8}, {"termo": "Primeira passagem", "tecnica": "Metabolismo", "definicao": "Metabolismo intestinal e hepático antes de a droga atingir a circulação sistêmica.", "slide": 8}, {"termo": "Clearance (CL)", "tecnica": "Parâmetro", "definicao": "Volume de plasma depurado por unidade de tempo; define a dose de manutenção.", "slide": 16}, {"termo": "Volume de distribuição (Vd)", "tecnica": "Parâmetro", "definicao": "Volume aparente que relaciona dose e concentração; define a dose de ataque.", "slide": 11}, {"termo": "Indutor enzimático", "tecnica": "Interação", "definicao": "Fármaco que acelera o metabolismo, como rifampicina e carbamazepina, reduzindo níveis.", "slide": 14}, {"termo": "Ordem zero", "tecnica": "Cinética", "definicao": "Eliminação de quantidade constante por tempo, com enzimas saturadas, como etanol e fenitoína em doses altas.", "slide": 18}], "caso": {"titulo": "Caso: sangramento com varfarina e fluconazol", "perfil": "Interação por inibição do metabolismo e risco de sangramento.", "etapas": [{"titulo": "Etapa 1: mecanismo", "texto": "Homem de 67 anos com fibrilação atrial, em varfarina com INR estável em 2,5. Recebe fluconazol por candidíase esofágica. Após cinco dias, apresenta equimoses e gengivorragia, com INR de 6,8.", "perguntas": [{"pergunta": "Qual é o mecanismo mais provável da interação?", "alts": ["Inibição enzimática pelo fluconazol, que eleva a concentração da varfarina", "Indução enzimática pelo fluconazol, que reduz a concentração da varfarina", "Competição pela albumina, que reduz o Vd da varfarina", "Alcalinização urinária, que acelera a excreção renal da varfarina", "Redução da filtração glomerular, que retém a varfarina no plasma"], "erradas": ["Fluconazol é inibidor, e não indutor, por essa via.", "Competição pela albumina tem efeito transitório, e não explica o quadro.", "Alcalinização urinária acelera a eliminação de ácidos fracos, e não o efeito descrito.", "A filtração reduzida não é o mecanismo citado para essa interação."], "justificativa": "Inibidores como fluconazol reduzem o metabolismo pelo CYP e elevam os níveis do fármaco (slide 14). A varfarina é metabolizada principalmente pelo CYP2C9 (slide 12)."}]}, {"titulo": "Etapa 2: conduta", "texto": "A equipe avalia o risco de sangramento. A aula destaca que o efeito de uma interação pode aparecer em dias, conforme a meia-vida e a mudança de níveis.", "perguntas": [{"pergunta": "Qual é a conduta mais adequada diante de INR de 6,8 com sangramento, segundo a lógica da aula?", "alts": ["Suspender a varfarina e avaliar o risco de sangramento com monitoramento", "Manter a dose e aumentar o fluconazol para corrigir o INR", "Dobrar a dose de varfarina para compensar a interação", "Trocar o fluconazol por rifampicina, que é indutora", "Ignorar o INR e reavaliar apenas após duas semanas"], "erradas": ["Manter a dose com fluconazol agrava a interação.", "Aumentar o fluconazol eleva ainda mais a concentração da varfarina.", "Dobrar a dose aumenta o risco de sangramento.", "Adiar a reavaliação expõe o paciente a sangramento grave."], "justificativa": "Com a interação, os níveis sobem gradualmente após o início e caem ao suspender; a conduta é suspender e monitorar, pois o risco é de toxicidade (slide 14)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um fármaco ácido fraco é administrado em estômago de pH ácido. Por que a absorção é favorecida, segundo a aula?", "alternativas": ["A forma ionizada predomina em pH ácido e atravessa melhor a membrana", "O pH não altera a ionização de ácidos fracos", "A absorção é mediada por carreador ativo independente do pH", "Forma não ionizada, em pH ácido", "A endocitose é a única via de passagem em qualquer pH"], "gabarito": "D", "justificativa": "Ácidos fracos ficam mais não ionizados em pH ácido, e só a forma não ionizada atravessa bem a membrana (Aula 2, slide 4).", "tecnica": "Ionização e pH", "slide": 4, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um fármaco tem Vd de 1 L/kg, de baixo acúmulo tecidual. Por que o Vd pequeno indica retenção no plasma, e qual exemplo a aula cita?", "alternativas": ["Permanece no plasma; exemplo: varfarina", "Acumula no tecido adiposo; exemplo: amiodarona", "É eliminado pela bile; exemplo: rifampicina", "É metabolizado no intestino; exemplo: nitroglicerina", "É filtrado no glomérulo; exemplo: vancomicina"], "gabarito": "A", "justificativa": "Vd baixo indica retenção no plasma, como na varfarina; Vd alto indica acúmulo tecidual, como na amiodarona (Aula 2, slide 11).", "tecnica": "Volume de distribuição", "slide": 11, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um paciente hipoalbuminêmico recebe fenitoína. Qual fração aumenta, e por que isso importa para o efeito clínico?", "alternativas": ["A fração ligada, que é a ativa e a excretável", "A fração biliar, que é a eliminada pelo fígado", "A fração metabólica, que é a absorvida pelo intestino", "A fração filtrada, que é a inativa", "A fração livre, que é a ativa e a eliminável"], "gabarito": "E", "justificativa": "Só a fração livre é ativa e eliminada; hipoalbuminemia aumenta a fração livre, como na fenitoína (Aula 2, slide 11).", "tecnica": "Ligação a proteínas", "slide": 11, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um fármaco com alta extração hepática é dado por via oral. Qual conceito explica a dose oral maior que a IV, e qual a via que evita isso?", "alternativas": ["Clearance renal; a via intramuscular evita o clearance", "Ligação a proteínas; a via oral evita a ligação", "Primeira passagem; sublingual evita", "Volume de distribuição; a via retal aumenta o Vd", "Ordem zero; a via transdérmica elimina a ordem zero"], "gabarito": "C", "justificativa": "A primeira passagem reduz a biodisponibilidade oral; vias sublingual, IV e transdérmica evitam o efeito (Aula 2, slide 8).", "tecnica": "Primeira passagem", "slide": 8, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um paciente tem falha terapêutica com um contraceptivo após início de rifampicina. Qual mecanismo a aula descreve e qual a direção do efeito?", "alternativas": ["Inibição enzimática, com metabolismo lento e aumento da concentração", "Indução enzimática, com queda da concentração", "Inibição de transportador renal, com retenção do contraceptivo", "Aumento da ligação a proteínas, com queda da fração livre", "Indução da absorção intestinal, com aumento da biodisponibilidade"], "gabarito": "B", "justificativa": "Rifampicina é indutora enzimática; a indução acelera o metabolismo e reduz a concentração do contraceptivo (Aula 2, slide 14).", "tecnica": "Indução enzimática", "slide": 14, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente com sinvastatina recebe claritromicina e apresenta miopatia. Qual enzima é inibida, e qual é o efeito sobre o fármaco?", "alternativas": ["CYP2D6 induzida, com queda da concentração de sinvastatina", "Glicoproteína-P induzida, com aumento de excreção biliar", "COMT inibida, com acúmulo de catecolaminas no músculo", "CYP3A4 inibida, com mais sinvastatina", "MAO inibida, com aumento de serotonina no músculo"], "gabarito": "D", "justificativa": "Claritromicina inibe o CYP3A4, elevando a sinvastatina e levando a miopatia (Aula 2, slides 12 e 14).", "tecnica": "Inibição enzimática", "slide": 14, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Uma dose de ataque de um fármaco é calculada. Qual parâmetro entra na fórmula, além da concentração alvo e da biodisponibilidade?", "alternativas": ["Clearance (CL), usado na manutenção", "Volume de distribuição (Vd)", "Meia-vida isolada", "Tmáx", "AUC isolada"], "gabarito": "B", "justificativa": "Dose de ataque = Vd × C alvo ÷ F; a dose de manutenção usa CL (Aula 2, slide 16).", "tecnica": "Parâmetros de dose", "slide": 16, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um fármaco com meia-vida de 10 horas é dado em doses repetidas. Quantas horas são necessárias para atingir 94 a 97% do equilíbrio, e por que a conta vale?", "alternativas": ["Cerca de 10 horas, pois uma meia-vida basta", "Cerca de 20 horas, pois são duas meias-vidas", "Cerca de 100 horas, pois são 10 meias-vidas", "Cerca de 40 a 50 horas", "Não há relação com a meia-vida, só com a dose"], "gabarito": "D", "justificativa": "Após 4 a 5 meias-vidas, o equilíbrio clínico é de 94 a 97% (Aula 2, slide 17).", "tecnica": "Doses repetidas", "slide": 17, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Pequeno aumento de dose de fenitoína causa grande aumento de concentração. Qual cinética explica isso, e qual é o padrão de eliminação?", "alternativas": ["Primeira ordem; fração constante por tempo com meia-vida curta", "Ordem zero; eliminação por filtração renal de fração livre", "Ordem zero, com enzimas saturadas", "Primeira ordem; eliminação biliar de metabólitos conjugados", "Ordem mista; absorção saturada com excreção por pulmão"], "gabarito": "C", "justificativa": "Na ordem zero, as enzimas saturadas eliminam quantidade constante; a fenitoína é citada como exemplo em doses altas (Aula 2, slide 18).", "tecnica": "Cinética de ordem zero", "slide": 18, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um paciente com cirrose recebe um fármaco de alta extração hepática. O que a aula prevê sobre a exposição, e por quê?", "alternativas": ["Diminui, pois a cirrose aumenta o metabolismo hepático", "Aumenta, pois a primeira passagem cai com o shunt portossistêmico", "Não muda, pois a extração hepática independe do fígado", "Diminui, pois a albumina aumenta a ligação ao fármaco", "Aumenta, pois a excreção biliar cai e o fármaco se acumula no sangue"], "gabarito": "B", "justificativa": "Na cirrose ou shunt portossistêmico, a primeira passagem cai e a exposição aumenta (Aula 2, slide 8).", "tecnica": "Populações especiais", "slide": 8, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Uma interação entre varfarina e fluconazol eleva o INR. Qual CYP a aula associa à varfarina, e qual o efeito do fluconazol?", "alternativas": ["CYP3A4, e o fluconazol induz, reduzindo a varfarina", "CYP2D6, e o fluconazol é inativo nessa via", "CYP1A2, e o fluconazol induz, reduzindo a varfarina", "CYP2C19, e o fluconazol não tem efeito enzimático", "CYP2C9, e o fluconazol inibe, elevando a varfarina"], "gabarito": "E", "justificativa": "A varfarina é metabolizada principalmente pelo CYP2C9; fluconazol é inibidor enzimático, elevando a concentração (Aula 2, slides 12 e 14; complementa a farmacologia clínica).", "tecnica": "Interação clínica", "slide": 14, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um fármaco ácido é eliminado por via renal. Como a alcalinização da urina afeta a eliminação, segundo a aula?", "alternativas": ["Retarda a eliminação de ácidos fracos, por reabsorção aumentada", "Não tem efeito, pois a eliminação renal independe do pH", "Acelera a eliminação de ácidos fracos", "Acelera a eliminação de bases fracas, como anestésicos locais", "Reduz a filtração glomerular do fármaco"], "gabarito": "C", "justificativa": "A reabsorção passiva depende do pH urinário; alcalinizar acelera a eliminação de ácidos fracos (Aula 2, slide 15).", "tecnica": "Excreção renal", "slide": 15, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um medicamento tem t½ = 0,693 × Vd ÷ CL. Se o clearance dobra e o Vd permanece igual, o que acontece com a meia-vida?", "alternativas": ["Cai pela metade", "Dobra", "Permanece igual", "Quadruplica", "Torna-se zero"], "gabarito": "A", "justificativa": "t½ = 0,693 × Vd ÷ CL: se CL dobra, a meia-vida cai pela metade (Aula 2, slide 16).", "tecnica": "Parâmetros de dose", "slide": 16, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Na tabela de vias de administração da aula, qual via tem a menor faixa de biodisponibilidade?", "alternativas": ["Retal, de 30 a menos de 100%", "Subcutânea, de 75 a 100%", "Transdérmica, de 80 a 100%", "Intramuscular, de 75 a 100%", "Oral, de 5 a menos de 100%"], "gabarito": "E", "justificativa": "A via oral tem a faixa mais ampla e baixa, de 5 a menos de 100%, pela primeira passagem (Aula 2, slide 7).", "tecnica": "Vias e biodisponibilidade", "slide": 7, "pdf": "pdf/gilmar/aula-02.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Para que um genérico seja considerado equivalente ao medicamento de referência, qual faixa de razão de velocidade e extensão de absorção a aula exige?", "alternativas": ["80% a 125% do valor da referência", "50% a 150% do valor da referência", "90% a 110% do valor da referência", "70% a 130% do valor da referência", "100% a 200% do valor da referência"], "gabarito": "A", "justificativa": "Os parâmetros de velocidade e extensão devem ficar entre 80% e 125% da referência (Aula 2, slide 9).", "tecnica": "Bioequivalência", "slide": 9, "pdf": "pdf/gilmar/aula-02.pdf"}], "id": "farma-gilmar-02", "titulo": "Aula 2", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-03"] = {"subtitulo": "Etapas do desenvolvimento de fármacos: pré-clínica, fases I a IV", "pdf": "pdf/gilmar/aula-03.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 3 · Etapas do desenvolvimento de fármacos (Prof. Dr. Gilmar S. Erzinger)", "FDA; ICH E6, E8 e M3; Anvisa; Brunton e Knollmann (Goodman & Gilman), citados nos slides"], "tabela": {"titulo": "Fases clínicas (slide 29)", "colunas": ["Fase", "Participantes", "Objetivo principal", "Pergunta-chave"], "linhas": [["I", "Voluntários saudáveis e/ou pacientes", "Segurança, tolerabilidade, PK/PD", "Qual dose e exposição são toleráveis?"], ["II", "Pacientes", "Eficácia inicial, dose e segurança", "Funciona, e qual dose ou regime usar?"], ["III", "Pacientes", "Confirmar eficácia e segurança", "O benefício é consistente e clinicamente relevante?"], ["IV", "População em uso real", "Farmacovigilância e efetividade", "O que ocorre após ampla utilização?"]]}, "resumo": [{"titulo": "1. Visão geral do desenvolvimento", "pontos": [{"t": "Tempo e custo", "sub": ["Tempo total típico: 10 a 15 anos da descoberta à aprovação (slide 3).", "Custo estimado: US$ 1 a 2,6 bilhões por fármaco aprovado, incluindo fracassos (slide 4; estimativas variam, como em DiMasi et al., 2016).", "Funil: 5.000 a 10.000 compostos na descoberta; cerca de 250 na pré-clínica; cerca de 5 nos ensaios clínicos; 1 aprovado (slide 4)."]}, {"t": "Autorização antes de humanos", "sub": ["Pesquisa com humanos exige autorização da agência reguladora (Anvisa no Brasil, FDA nos EUA) e aprovação ética (CEP/Conep no Brasil) (slide 12).", "Boas Práticas Clínicas: ICH E6 (slide 12)."]}]}, {"titulo": "2. Descoberta e pré-clínica", "pontos": [{"t": "Descoberta", "sub": ["Alvo biológico validado; triagem de alto rendimento (HTS) e modelagem in silico; composto-líder; otimização estrutura-atividade (slide 7).", "Origens: síntese, produtos naturais, biotecnologia ou reposicionamento (slide 6)."]}, {"t": "Estudos não clínicos", "sub": ["In vitro e in vivo: farmacodinâmica, farmacocinética (ADME), toxicologia aguda e de doses repetidas, genotoxicidade, toxicidade reprodutiva e carcinogenicidade quando indicadas (slide 8).", "Estudos sob Boas Práticas de Laboratório (BPL), em geral em roedor e não roedor; princípios dos 3Rs (ICH M3, slide 33)."]}, {"t": "Perguntas que a pré-clínica responde", "sub": ["O fármaco tem o efeito esperado? Qual a relação dose-exposição-efeito? Quais órgãos podem ser afetados? Qual a margem de segurança? Qual dose inicial em humanos? (slide 10)."]}]}, {"titulo": "3. Fase I", "pontos": [{"t": "Desenho e objetivo", "sub": ["20 a 100 participantes, em geral voluntários sadios; meses a 1 ano; cerca de 70% avançam (slide 14).", "Objetivo: segurança, tolerabilidade, farmacocinética e farmacodinâmica; definir dose máxima tolerada (slides 14 e 15).", "Desenhos: SAD (dose única crescente) e MAD (doses repetidas crescentes); estudo do efeito da alimentação (food effect) (slide 16)."]}, {"t": "Exceção", "sub": ["Em oncologia e fármacos muito tóxicos, a fase I é feita diretamente em pacientes (slide 14)."]}]}, {"titulo": "4. Fase II", "pontos": [{"t": "Desenho", "sub": ["100 a 300 pacientes com a doença-alvo; até 2 anos; cerca de 33% avançam (slide 17).", "Objetivo: prova de conceito, relação dose-resposta e esquema posológico (slide 17).", "Randomizado e controlado: grupo do fármaco × placebo ou tratamento padrão; a randomização reduz a chance de vieses (slide 18)."]}, {"t": "Leitura do resultado", "sub": ["Exemplo do slide 20: redução de 8 mmHg no fármaco × 3 mmHg no controle; diferença de −5 mmHg sugere atividade terapêutica (slide 20).", "É a fase de maior fracasso; muitos candidatos não mostram eficácia suficiente (slide 17)."]}]}, {"titulo": "5. Fase III", "pontos": [{"t": "Desenho", "sub": ["300 a 3.000 ou mais pacientes, em vários centros; 1 a 4 anos; 25 a 30% chegam ao registro (slide 21).", "Estudos pivotais: randomizados, duplo-cegos e multicêntricos; comparação com placebo ou padrão (slide 21).", "Detecta reações adversas menos frequentes e confirma a eficácia em população mais diversa (slide 21)."]}, {"t": "Base do registro", "sub": ["Os resultados da fase III são a base principal do pedido de registro (slide 22)."]}]}, {"titulo": "6. Registro e fase IV", "pontos": [{"t": "Registro", "sub": ["Anvisa avalia qualidade (fabricação, controle e estabilidade), segurança (pré e clínica), eficácia (estudos pivotais) e relação benefício-risco, com bula e inspeção de Boas Práticas de Fabricação (slide 26).", "FDA (EUA) e EMA (União Europeia) seguem lógica semelhante (slide 26)."]}, {"t": "Farmacovigilância", "sub": ["Milhares a milhões de usuários; detecta reações raras e tardias; avalia populações especiais e interações (slide 27).", "Notificação no Brasil pelo VigiMed (slide 27).", "Exemplo: rofecoxibe (Vioxx), retirado em 2004 por aumento do risco cardiovascular (slide 27)."]}, {"t": "Eficácia × efetividade", "sub": ["Eficácia: desempenho em condições controladas. Efetividade: desempenho na prática real (slide 28)."]}]}, {"titulo": "7. Por que um programa para", "pontos": [{"t": "Causas", "sub": ["Falta de eficácia ou benefício clínico; problemas de segurança; perfil farmacocinético inadequado; formulação, estabilidade ou produção; interações; razões comerciais (slide 30)."]}]}, {"titulo": "8. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Objetivo de cada fase e número típico de participantes.", "Por que a randomização e o grupo controle importam (fase II e III).", "O que só a fase IV consegue detectar."]}]}], "glossario": [{"termo": "Fase I", "tecnica": "Ensaio clínico", "definicao": "Primeiros estudos em humanos, para segurança, tolerabilidade e farmacocinética.", "slide": 14}, {"termo": "SAD e MAD", "tecnica": "Fase I", "definicao": "Single Ascending Dose (dose única crescente) e Multiple Ascending Dose (doses repetidas crescentes).", "slide": 16}, {"termo": "FIH", "tecnica": "Fase I", "definicao": "First-in-human: primeira administração do candidato em seres humanos.", "slide": 16}, {"termo": "Estudo pivotal", "tecnica": "Fase III", "definicao": "Estudo randomizado, duplo-cego e multicêntrico, base do pedido de registro.", "slide": 21}, {"termo": "Randomização", "tecnica": "Desenho do ensaio", "definicao": "Distribuição aleatória dos participantes para os grupos, reduzindo vieses.", "slide": 18}, {"termo": "Farmacovigilância", "tecnica": "Fase IV", "definicao": "Monitoramento de reações adversas após a comercialização; no Brasil, notificação pelo VigiMed.", "slide": 27}, {"termo": "BPL", "tecnica": "Pré-clínica", "definicao": "Boas Práticas de Laboratório, padrão dos estudos não clínicos.", "slide": 8}], "caso": {"titulo": "Caso: novo fármaco para insuficiência cardíaca", "perfil": "Decisões em cada etapa do desenvolvimento.", "etapas": [{"titulo": "Etapa 1: onde estamos", "texto": "Uma empresa tem uma molécula para insuficiência cardíaca. Os estudos mostram atividade em modelos animais, mas ainda não há dados em humanos. A equipe precisa decidir o próximo passo.", "perguntas": [{"pergunta": "Qual é o próximo passo adequado, segundo a aula?", "alts": ["Obter autorização da agência e aprovação ética antes da primeira dose em humanos", "Lançar o produto no mercado, com a fase IV como único estudo", "Iniciar a fase III com milhares de pacientes sem fase I", "Dispensar a farmacocinética, pois a atividade já foi mostrada", "Testar em voluntários sem qualquer protocolo ou consentimento"], "erradas": ["Registro sanitário vem depois de todas as fases clínicas.", "Fase III sem fase I e II não é o caminho descrito.", "A farmacocinética é exigida antes da dose em humanos.", "Consentimento e protocolo são obrigatórios antes da inclusão de participantes."], "justificativa": "Antes de testar em humanos é preciso autorização da agência reguladora e aprovação ética (slides 3 e 12)."}]}, {"titulo": "Etapa 2: fase II", "texto": "Em um estudo de fase II com 200 pacientes, o grupo do novo fármaco reduz a pressão arterial em média 8 mmHg, e o grupo placebo, 3 mmHg.", "perguntas": [{"pergunta": "Qual é a interpretação mais adequada, segundo a aula?", "alts": ["Diferença de 5 mmHg sugere atividade terapêutica preliminar", "Prova definitiva de eficácia, dispensando a fase III", "Redução de 8 mmHg prova ausência de efeito placebo", "Diferença sem relevância, pois fase II não compara grupos", "Evidência de toxicidade, pelo efeito de 8 mmHg"], "erradas": ["Fase II não confirma eficácia; a fase III é que confirma.", "Uma redução de 8 mmHg não prova ausência de efeito placebo, que o grupo controle mede.", "Fase II compara grupos randomizados, por definição.", "A redução de pressão é o efeito desejado, e não toxicidade."], "justificativa": "Na fase II, a diferença entre grupos sugere atividade; a fase III confirma a eficácia (slides 19, 20 e 21)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um laboratório afirma que seu fármaco será aprovado após a fase II. Qual erro conceitual a aula identifica nessa afirmação?", "alternativas": ["A fase II é o registro sanitário, que dispensa estudos de fase III", "A fase II não confirma eficácia", "A fase II é só farmacovigilância, sem avaliação de eficácia", "A fase II testa apenas voluntários sadios em dose única", "A fase II é feita após a comercialização, em uso real"], "gabarito": "B", "justificativa": "Fase II dá prova de conceito; a fase III confirma eficácia e é a base do registro (Aula 3, slides 17 e 21 a 22).", "tecnica": "Fases clínicas", "slide": 21, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Em um ensaio de fase II, o grupo do fármaco reduz 8 mmHg e o controle reduz 3 mmHg. Qual é a leitura correta e qual é o limite dela?", "alternativas": ["Diferença de −5 mmHg prova eficácia e dispensa fase III", "Redução de 8 mmHg prova ausência de efeito placebo", "Diferença sem relevância, pois fase II não tem grupo controle", "Evidência de toxicidade, pelo efeito de 8 mmHg", "Diferença de −5 mmHg sugere atividade"], "gabarito": "E", "justificativa": "A diferença sugere atividade terapêutica; a confirmação é da fase III (Aula 3, slide 20).", "tecnica": "Leitura de fase II", "slide": 20, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Por que a randomização é essencial em um ensaio clínico controlado, segundo a aula?", "alternativas": ["Reduz diferenças entre grupos", "Garante que todos os participantes recebam o mesmo tratamento", "Elimina a necessidade de grupo controle em qualquer ensaio", "Aumenta a dose do fármaco em cada grupo do estudo", "Substitui o consentimento informado dos participantes"], "gabarito": "A", "justificativa": "A randomização reduz a possibilidade de que diferenças entre grupos sejam responsáveis pelos resultados (Aula 3, slide 18).", "tecnica": "Randomização", "slide": 18, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um fármaco entra em fase I. Qual é o objetivo principal e a população típica, segundo a aula?", "alternativas": ["Segurança, tolerabilidade e farmacocinética", "Eficácia em 300 a 3.000 pacientes, em vários centros", "Farmacovigilância em milhões de usuários após o registro", "Prova de conceito em 100 a 300 pacientes com a doença-alvo", "Confirmação de eficácia com estudo pivotal de dupla ocultação"], "gabarito": "A", "justificativa": "Na fase I, o objetivo é segurança e PK, em geral com 20 a 100 voluntários sadios (Aula 3, slide 14).", "tecnica": "Fase I", "slide": 14, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Em oncologia, por que a fase I é feita diretamente em pacientes, segundo a aula?", "alternativas": ["Porque o registro exige pacientes na fase I", "Porque voluntários sadios não podem receber dose única", "Porque a fase I dispensa avaliação de segurança nessa área", "Porque a oncologia não usa estudos pré-clínicos", "Porque fármacos muito tóxicos"], "gabarito": "E", "justificativa": "Em oncologia e fármacos muito tóxicos, a fase I é feita diretamente em pacientes (Aula 3, slide 14).", "tecnica": "Fase I em oncologia", "slide": 14, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um estudo testa doses repetidas crescentes em voluntários. Qual é o nome do desenho, e qual pergunta ele responde?", "alternativas": ["SAD (single ascending dose), para eficácia em pacientes", "FIH (first-in-human), para registro sanitário", "Estudo pivotal, para comparação com placebo", "MAD, com doses repetidas crescentes", "Estudo de farmacovigilância, para reações raras"], "gabarito": "D", "justificativa": "MAD é doses repetidas crescentes; SAD é dose única crescente (Aula 3, slide 16).", "tecnica": "Desenho da fase I", "slide": 16, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um fármaco é avaliado em estudo de fase III, com estudos pivotais. Quais características esses estudos têm, segundo a aula?", "alternativas": ["Randomizados, duplo-cegos e multicêntricos", "Abertos, com voluntários sadios e dose única", "Observacionais, sem grupo de comparação", "Restritos a um centro, sem randomização", "Exclusivamente em animais de duas espécies"], "gabarito": "A", "justificativa": "Estudos pivotais são randomizados, duplo-cegos e multicêntricos (Aula 3, slide 21).", "tecnica": "Estudos pivotais", "slide": 21, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Quais são as informações que só podem surgir na fase IV, segundo a aula?", "alternativas": ["Dose máxima tolerada em voluntários sadios", "Farmacocinética de dose única em animais", "Reações adversas raras, em larga escala", "Eficácia em pacientes com 20 participantes", "Toxicidade reprodutiva em roedores"], "gabarito": "C", "justificativa": "Reações raras só são detectáveis em larga escala, na fase IV (Aula 3, slide 27).", "tecnica": "Fase IV", "slide": 27, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um fármaco é retirado do mercado após aumento de risco cardiovascular detectado em uso real. Qual exemplo a aula cita, e em que ano?", "alternativas": ["Ácido acetilsalicílico, em 1998", "Ibuprofeno, em 2010", "Celecoxibe, em 2015", "Rofecoxibe (Vioxx), em 2004", "Propranolol, em 1975"], "gabarito": "D", "justificativa": "O rofecoxibe foi retirado em 2004 após evidências de risco cardiovascular (Aula 3, slide 27).", "tecnica": "Farmacovigilância", "slide": 27, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um fármaco funciona muito bem em um ensaio controlado, mas tem resultado modesto na prática. Como a aula explica essa diferença?", "alternativas": ["Efetividade é o desempenho controlado; eficácia é o desempenho na prática", "Eficácia e efetividade são sinônimos, então a diferença é erro de medida", "Eficácia é medida só na fase IV; efetividade só na fase I", "Eficácia é em controle; efetividade é na prática", "Efetividade depende do custo; eficácia depende da dose"], "gabarito": "D", "justificativa": "Eficácia é em condições controladas; efetividade é na prática real (Aula 3, slide 28).", "tecnica": "Eficácia × efetividade", "slide": 28, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Quantos compostos, em média, chegam aos ensaios clínicos a partir de 5.000 a 10.000 avaliados na descoberta?", "alternativas": ["Cerca de 250", "Cerca de 1.000", "Cerca de 50", "Cerca de 10.000", "Cerca de 5"], "gabarito": "E", "justificativa": "Da descoberta, cerca de 250 entram na pré-clínica e cerca de 5 chegam aos ensaios clínicos (Aula 3, slide 4).", "tecnica": "Funil de desenvolvimento", "slide": 4, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Quais espécies a aula indica para os estudos pré-clínicos conduzidos sob BPL, e qual princípio ético os orienta?", "alternativas": ["Apenas roedores, sob a regra de custo mínimo", "Roedor e não roedor, sob os 3Rs", "Apenas primatas, sob a regra de semelhança genética", "Apenas células in vitro, sem princípio ético", "Apenas voluntários sadios, sob consentimento informado"], "gabarito": "B", "justificativa": "Os estudos são em geral em roedor e não roedor, com os 3Rs (Aula 3, slide 8).", "tecnica": "Pré-clínica", "slide": 8, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "A pré-clínica precisa responder se a dose inicial em humanos é segura. Qual conceito relacionado a essa pergunta a aula cita?", "alternativas": ["Janela imunológica", "Margem de segurança", "Biodisponibilidade absoluta", "Janela terapêutica do registro", "Razão de chances do ensaio"], "gabarito": "B", "justificativa": "A pré-clínica deve estimar a margem de segurança e a dose inicial (Aula 3, slide 10).", "tecnica": "Pré-clínica", "slide": 10, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um programa de fármaco é interrompido mesmo com molécula ativa. Quais razões a aula lista além da falta de eficácia?", "alternativas": ["Apenas o custo de produção, sem outros fatores", "Apenas a falta de registro na Anvisa, sem fatores clínicos", "Segurança, farmacocinética ruim e razões comerciais", "Apenas o tamanho da amostra, sem fatores de segurança", "Apenas o nome comercial, sem fatores técnicos"], "gabarito": "C", "justificativa": "Além da eficácia, a aula cita segurança, farmacocinética, formulação, interações e razões comerciais (Aula 3, slide 30).", "tecnica": "Causas de interrupção", "slide": 30, "pdf": "pdf/gilmar/aula-03.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um fármaco mostra efeito na fase II, mas a dose-resposta não está definida. Qual objetivo da fase II, segundo a aula, ainda não foi atingido?", "alternativas": ["Farmacovigilância de longo prazo em milhões de usuários", "Confirmação de eficácia em 3.000 pacientes em vários centros", "Estabelecer a relação dose-resposta e o esquema posológico", "Obtenção do registro sanitário pela Anvisa", "Estudo de efeito da alimentação na absorção"], "gabarito": "C", "justificativa": "Na fase II, um objetivo é estabelecer dose-resposta e esquema posológico (Aula 3, slide 17).", "tecnica": "Objetivos da fase II", "slide": 17, "pdf": "pdf/gilmar/aula-03.pdf"}], "id": "farma-gilmar-03", "titulo": "Aula 3", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-04"] = {"subtitulo": "Colinérgicos e anticolinérgicos, anticolinesterásicos e nicotínicos", "pdf": "pdf/gilmar/aula-04.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 4 · Colinérgicos e Anticolinérgicos (Prof. Dr. Gilmar S. Erzinger)", "Brunton e Knollmann (Goodman & Gilman); Katzung (citados nos slides)"], "tabela": {"titulo": "Receptores colinérgicos (slide 8)", "colunas": ["Tipo", "Localização principal", "Mecanismo", "Efeito da ativação"], "linhas": [["M1", "SNC, gânglios, células parietais", "Gq → IP3/DAG, ↑Ca²⁺", "Cognição, ↑ secreção gástrica"], ["M2", "Coração (nós SA e AV)", "Gi → ↓AMPc, abre canais K⁺", "↓ frequência cardíaca, ↓ condução AV"], ["M3", "Músculo liso, glândulas, endotélio", "Gq → IP3/DAG, ↑Ca²⁺", "Contração, secreção, vasodilatação via NO"], ["M4 / M5", "SNC", "Gi / Gq", "Modulação central"], ["NN", "Gânglios, medula adrenal, SNC", "Canal iônico (Na⁺/K⁺)", "Despolarização ganglionar, liberação de catecolaminas"], ["NM", "Placa motora", "Canal iônico (Na⁺/K⁺)", "Contração do músculo esquelético"]]}, "resumo": [{"titulo": "1. Transmissão colinérgica", "pontos": [{"t": "Organização do SNA", "sub": ["Parassimpático: origem craniossacral (NC III, VII, IX, X, S2 a S4); pré-ganglionar ACh em NN; pós-ganglionar ACh em muscarínico; função de repouso e digestão (slide 3).", "Simpático: origem toracolombar (T1 a L2); pré-ganglionar ACh em NN; pós-ganglionar noradrenalina; exceções: glândulas sudoríparas (ACh em M3) e medula adrenal (adrenalina) (slide 3)."]}, {"t": "Ciclo da acetilcolina", "sub": ["Captação de colina pelo CHT (bloqueado pelo hemicolínio), que é a etapa limitante (slide 5).", "Síntese pela colina acetiltransferase; armazenamento pelo VAChT (bloqueado pelo vesamicol) (slide 5).", "Liberação dependente de Ca²⁺ e SNARE; toxina botulínica impede (slide 5).", "Término: AChE hidrolisa a ACh em colina e acetato, em microssegundos (slide 5)."]}]}, {"titulo": "2. Receptores", "pontos": [{"t": "Muscarínicos", "sub": ["M1 (SNC, gânglios, parietais): Gq. M2 (coração): Gi, ↓ frequência e condução. M3 (músculo liso, glândulas, endotélio): Gq; no endotélio libera NO. M4 e M5: SNC (slide 8).", "Mnemônico: ímpares (M1, M3, M5) são Gq; pares (M2, M4) são Gi (slide 8)."]}, {"t": "Nicotínicos", "sub": ["Canais iônicos; resposta rápida. NN em gânglios autonômicos e medula adrenal; NM na junção neuromuscular do músculo esquelético (slides 16 e 41)."]}, {"t": "Diferenças", "sub": ["Muscarínico: acoplado à proteína G, resposta mais lenta. Nicotínico: canal iônico, resposta rápida (slide 17)."]}]}, {"titulo": "3. Agonistas colinérgicos", "pontos": [{"t": "Diretos", "sub": ["Betanecol: retenção urinária e atonia gastrointestinal pós-operatória (slide 25). Pilocarpina: glaucoma e xerostomia (slides 25 e 29). Carbacol: M e N (slide 29)."]}, {"t": "Indiretos (anticolinesterásicos)", "sub": ["Neostigmina: miastenia e reversão de bloqueio neuromuscular. Piridostigmina: miastenia crônica. Donepezila: Alzheimer (slide 21)."]}, {"t": "Efeitos sistêmicos e adversos", "sub": ["SLUDGE: salivação, lacrimejamento, urina, diarreia, cólica e êmese (slide 30).", "Contraindicações: asma, DPOC, úlcera péptica, obstrução mecânica; cautela com bradiarritmias e hipertireoidismo (slide 30)."]}]}, {"titulo": "4. Miastenia gravis", "pontos": [{"t": "Fisiopatologia", "sub": ["Autoanticorpos contra o receptor nicotínico da placa motora; fraqueza que piora com o esforço, ptose e diplopia (slides 22 a 24).", "Tratamento: piridostigmina várias vezes ao dia; corticoide, imunossupressores e timectomia como modificadores; crise: imunoglobulina IV ou plasmaférese e suporte ventilatório (slide 23).", "A piridostigmina não elimina anticorpos; aumenta a ACh disponível (slide 24)."]}, {"t": "Crise miastênica × crise colinérgica", "sub": ["Miastênica: dose insuficiente ou piora; fraqueza sem sinais muscarínicos; melhora com mais anticolinesterásico (slide 26).", "Colinérgica: excesso de anticolinesterásico; miose, sialorreia, bradicardia, fasciculações; piora com mais anticolinesterásico (slide 26)."]}]}, {"titulo": "5. Antagonistas muscarínicos", "pontos": [{"t": "Atropina por dose", "sub": ["Cerca de 0,5 mg: boca seca, ↓ sudorese. 1 mg: taquicardia, sede. 2 mg: midríase, cicloplegia. 5 mg: retenção urinária, ↓ motilidade. 10 mg ou mais: agitação, delírio, alucinações, hipertermia e coma (slide 32)."]}, {"t": "Uso clínico", "sub": ["Atropina: bradicardia sintomática, intoxicação por organofosforados, antissialagogo. Escopolamina: cinetose. Butilescopolamina: cólicas. Ipratrópio e tiotrópio: DPOC. Tropicamida: midríase. Oxibutinina: bexiga hiperativa. Biperideno e triexifenidil: parkinsonismo medicamentoso. Glicopirrolato: antissialagogo e reversão de bloqueio neuromuscular (slide 33)."]}, {"t": "Aminas terciárias × quaternárias", "sub": ["Terciárias (atropina, escopolamina, biperideno, oxibutinina): atravessam a BHE; efeitos centrais (slide 37).", "Quaternárias (butilescopolamina, ipratrópio, tiotrópio, glicopirrolato): sem passagem para o SNC; efeito periférico (slide 37)."]}, {"t": "Síndrome anticolinérgica", "sub": ["Seco como osso, vermelho como pimentão, quente como fogo, cego como morcego, louco como chapeleiro (slide 38).", "Causas: atropina, Datura (trombeteira), antidepressivos tricíclicos e anti-histamínicos de primeira geração (slide 38).", "Evitar em glaucoma de ângulo fechado, retenção urinária, obstrução intestinal e idosos (slide 38)."]}]}, {"titulo": "6. Anticolinesterásicos e intoxicação", "pontos": [{"t": "Classes de inibidores", "sub": ["Reversíveis (edrofônio: minutos). Carbamatos (neostigmina, piridostigmina, fisostigmina, rivastigmina: 30 min a 6 h). Organofosforados (malation, clorpirifós, sarin, VX: inibição irreversível após envelhecimento) (slide 50).", "Quaternários (neostigmina, piridostigmina) não atravessam a BHE; terciários (fisostigmina, donepezila) atravessam (slide 51)."]}, {"t": "Intoxicação por organofosforados e carbamatos", "sub": ["Fontes: agrotóxicos, 'chumbinho' (com aldicarbe) e agentes de guerra (slide 53).", "Síndrome: muscarínica (miose, broncorreia, bradicardia), nicotínica (fasciculações, paralisia diafragmática), central (convulsão e coma) (slide 54).", "Tratamento: descontaminação; via aérea; atropina titulada até secar secreções; pralidoxima, que reativa a AChE antes do envelhecimento; benzodiazepínico para convulsão (slide 55).", "Síndrome intermediária de 24 a 96 h; neuropatia tardia de 1 a 3 semanas (organofosforados) (slide 56)."]}]}, {"titulo": "7. Nicotínicos", "pontos": [{"t": "Nicotina e vareniclina", "sub": ["Nicotina: ação bifásica nos gânglios (estimula e depois bloqueia); reposição no tabagismo (slide 40).", "Vareniclina: agonista parcial α4β2; efeitos como náusea e sonhos vívidos (slide 40)."]}, {"t": "Succinilcolina e bloqueio ganglionar", "sub": ["Succinilcolina: agonista NM com despolarização persistente da placa; paralisia temporária (slide 42).", "Bloqueio ganglionar: vence o tônus predominante; hipotensão, midríase, constipação e retenção urinária (slide 43)."]}]}, {"titulo": "8. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Diferenciar crise miastênica de crise colinérgica.", "Atropina reverte efeitos muscarínicos, mas não nicotínicos.", "Pralidoxima: só antes do envelhecimento da enzima."]}]}], "glossario": [{"termo": "Efeito teto", "tecnica": "Reversão de bloqueio neuromuscular", "definicao": "Limite de eficácia: aumentar a dose não aumenta o efeito, em bloqueio profundo.", "slide": 28}, {"termo": "Crise colinérgica", "tecnica": "Excesso de anticolinesterásico", "definicao": "Miose, sialorreia, bradicardia e fasciculações; piora com mais anticolinesterásico.", "slide": 26}, {"termo": "Envelhecimento da AChE", "tecnica": "Organofosforados", "definicao": "Fosforilação estável da serina; a oxima só reativa a enzima antes desse processo.", "slide": 56}, {"termo": "Síndrome anticolinérgica", "tecnica": "Toxicidade", "definicao": "Quadro de pele seca e quente, midríase, taquicardia, retenção urinária e delírio.", "slide": 38}, {"termo": "Aminas quaternárias", "tecnica": "Farmacocinética", "definicao": "Carga positiva permanente; absorção oral pobre e não atravessam a BHE.", "slide": 37}, {"termo": "Pralidoxima", "tecnica": "Antídoto", "definicao": "Oxima que reativa a AChE inibida por organofosforados, nos efeitos nicotínicos.", "slide": 55}], "caso": {"titulo": "Caso: chá de trombeteira", "perfil": "Síndrome anticolinérgica por Datura.", "etapas": [{"titulo": "Etapa 1: síndrome", "texto": "Jovem de 22 anos, após festa e chá de trombeteira, agitado e confuso, com alucinações visuais. Pele quente, seca e avermelhada; pupilas midriáticas e pouco reativas; FC 132 bpm; temperatura 38,9 °C; bexiga palpável; ruídos hidroaéreos diminuídos.", "perguntas": [{"pergunta": "Qual é a síndrome tóxica, segundo a aula?", "alts": ["Síndrome anticolinérgica", "Síndrome colinérgica por organofosforado", "Síndrome simpatomimética por anfetamina", "Síndrome da crise miastênica", "Síndrome serotoninérgica por inibidor da MAO"], "erradas": ["Síndrome colinérgica tem miose, sialorreia e bradicardia, o oposto do quadro.", "Simpatomimético causa midríase, mas com sudorese e taquicardia típicas.", "Crise miastênica é fraqueza sem sinais muscarínicos.", "Serotoninérgica não é a síndrome descrita para trombeteira."], "justificativa": "Seco como osso, vermelho, quente, cego e louco: síndrome anticolinérgica, causada por plantas como a Datura (slide 38)."}]}, {"titulo": "Etapa 2: mecanismo e conduta", "texto": "A equipe pergunta qual é o mecanismo do quadro e qual o papel da atropina nesse caso.", "perguntas": [{"pergunta": "Qual é o mecanismo mais adequado para o quadro?", "alts": ["Bloqueio dos receptores muscarínicos pela escopolamina e atropina da planta", "Inibição da acetilcolinesterase, com excesso de ACh na sinapse", "Ativação de receptores nicotínicos, com fasciculações generalizadas", "Bloqueio de receptores beta, com bradicardia intensa", "Inibição da MAO, com acúmulo de serotonina no SNC"], "erradas": ["Inibição da AChE é o mecanismo do organofosforado, não da trombeteira.", "Ativação nicotínica causa fasciculações, que não são o quadro descrito.", "Bloqueio beta causa bradicardia, e não taquicardia com pele quente.", "Inibição da MAO não é o mecanismo da síndrome anticolinérgica."], "justificativa": "Os alcaloides da planta bloqueiam os receptores muscarínicos, como a atropina (slides 34 e 38)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um paciente recebe um fármaco que bloqueia a enzima que degrada a acetilcolina. Qual é a classe e qual a consequência clínica imediata, segundo a aula?", "alternativas": ["Agonista muscarínico direto, sem efeito sobre a degradação da ACh", "Antagonista muscarínico, com redução de ACh na fenda", "Agonista nicotínico, com bloqueio da placa motora", "Anticolinesterásico indireto, mais ACh", "Antagonista beta, com redução da frequência cardíaca apenas"], "gabarito": "D", "justificativa": "Inibir a AChE aumenta ACh em todas as sinapses colinérgicas (Aula 4, slides 48 e 50).", "tecnica": "Anticolinesterásicos", "slide": 48, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um paciente tem fraqueza muscular com ptose e diplopia, que piora com o esforço. Qual é o mecanismo da doença e qual é o tratamento sintomático citado, com o raciocínio?", "alternativas": ["Autoanticorpos contra receptor; piridostigmina", "Bloqueio muscarínico pela atropina; neostigmina reduz a secreção", "Excesso de ACh no músculo; atropina reduz a contração", "Falha de MHC-I; pralidoxima reativa o receptor", "Defeito de IgE; corticoide bloqueia a placa motora"], "gabarito": "A", "justificativa": "Na miastenia há autoanticorpos contra o receptor nicotínico; piridostigmina compensa a falha de transmissão (Aula 4, slides 23 e 24).", "tecnica": "Miastenia gravis", "slide": 23, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um paciente tomou piridostigmina em dose alta e apresenta miose, sialorreia, bradicardia e fasciculações. Qual crise é essa, e qual é a conduta de piora com mais anticolinesterásico?", "alternativas": ["Crise miastênica, em que mais anticolinesterásico melhora o quadro", "Crise anticolinérgica, em que mais atropina melhora o quadro", "Crise alérgica, em que mais adrenalina piora o quadro", "Crise colinérgica, em que mais anticolinesterásico piora o quadro", "Crise de hipoglicemia, em que mais betabloqueador melhora o quadro"], "gabarito": "D", "justificativa": "A crise colinérgica é excesso de anticolinesterásico e piora com mais inibidor; a miastênica melhora (Aula 4, slide 26).", "tecnica": "Crise miastênica × colinérgica", "slide": 26, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um anestesista quer reverter bloqueio neuromuscular profundo com neostigmina. Qual é a limitação descrita e o motivo, segundo a aula?", "alternativas": ["Toxicidade cardíaca, pois a neostigmina é betabloqueadora", "Tolerância rápida, pois a neostigmina é metabolizada pela AChE", "Efeito teto, por falta de receptores", "Resistência por IgE, pois o bloqueio é alérgico", "Dependência de benzodiazepínico, pois a neostigmina é sedativa"], "gabarito": "C", "justificativa": "O efeito teto limita a reversão em bloqueio profundo (Aula 4, slide 28).", "tecnica": "Efeito teto", "slide": 28, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Neostigmina é usada para reverter bloqueio neuromuscular. Qual fármaco deve acompanhá-la, e por qual razão, segundo a aula?", "alternativas": ["Propranolol, para bloquear os efeitos nicotínicos da ACh", "Glicopirrolato ou atropina", "Adrenalina, para reverter a fraqueza muscular residual", "Pralidoxima, para reativar a acetilcolinesterase", "Succinilcolina, para potencializar a despolarização"], "gabarito": "B", "justificativa": "A neostigmina é associada a glicopirrolato ou atropina para controlar efeitos muscarínicos (Aula 4, slide 27).", "tecnica": "Reversão de BNM", "slide": 27, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um adulto recebe 10 mg de atropina por engano. Qual quadro a aula associa a essa dose?", "alternativas": ["Bradicardia leve, com boca seca apenas", "Agitação, delírio, hipertermia e coma", "Midríase isolada, sem sinais sistêmicos", "Broncorreia e miose puntiforme", "Hipotensão postural com sudorese profusa"], "gabarito": "B", "justificativa": "A partir de 10 mg, a atropina causa agitação, delírio, alucinações, hipertermia e coma (Aula 4, slide 32).", "tecnica": "Atropina por dose", "slide": 32, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Uma intoxicação por organofosforado é tratada com atropina. O que a atropina reverte e o que ela não reverte, segundo a aula?", "alternativas": ["Reverte os efeitos muscarínicos", "Reverte efeitos nicotínicos; não reverte efeitos muscarínicos", "Reverte a fraqueza e a sialorreia; não reverte a bradicardia", "Reverte apenas a midríase; não reverte qualquer efeito sistêmico", "Reverte todos os efeitos, pois é antídoto universal"], "gabarito": "A", "justificativa": "A atropina é antagonista muscarínica; não corrige efeitos nicotínicos (Aula 4, slide 30).", "tecnica": "Atropina na intoxicação", "slide": 30, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um paciente ingeriu um chá de planta e apresenta pele quente e seca, midríase e delírio. Qual mecanismo a aula atribui a essa síndrome?", "alternativas": ["Excesso de ACh, com síndrome colinérgica", "Ativação alfa-1, com vasoconstrição e hipertensão", "Inibição da COMT, com acúmulo de catecolaminas", "Bloqueio muscarínico, síndrome anticolinérgica", "Ativação de 5-HT2A, com síndrome serotoninérgica"], "gabarito": "D", "justificativa": "Plantas como a Datura causam síndrome anticolinérgica por bloqueio muscarínico (Aula 4, slide 38).", "tecnica": "Síndrome anticolinérgica", "slide": 38, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Por que o ipratrópio, uma amina quaternária, não causa efeitos centrais relevantes, segundo a aula?", "alternativas": ["É muito lipossolúvel, ficando retido no tecido adiposo", "É metabolizado no fígado antes de atingir a circulação", "Carga positiva permanente, pouca passagem na BHE", "Atua apenas em receptores nicotínicos do músculo", "Tem meia-vida muito longa, sem chegar ao SNC"], "gabarito": "C", "justificativa": "Quaternárias têm carga positiva permanente e não atravessam bem a BHE (Aula 4, slides 36 e 37).", "tecnica": "Aminas quaternárias", "slide": 37, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um agricultor é exposto a um organofosforado. Por que a pralidoxima precisa ser dada cedo, segundo a aula?", "alternativas": ["Ela atua após o envelhecimento, quando a AChE está plenamente ativa", "Ela impede a absorção cutânea do agente tóxico", "Ela só reativa a AChE antes do envelhecimento da enzima", "Ela aumenta o metabolismo hepático do organofosforado", "Ela bloqueia os receptores muscarínicos de forma definitiva"], "gabarito": "C", "justificativa": "A oxima só reativa a enzima antes do envelhecimento; por isso é precoce (Aula 4, slide 56).", "tecnica": "Pralidoxima", "slide": 56, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Qual é a diferença entre carbamatos e organofosforados quanto à enzima, segundo a aula?", "alternativas": ["Carbamatos fosforilam a serina de modo estável; organofosforados são reversíveis em minutos", "Carbamatos: hidrólise lenta; organofosforados: envelhecimento", "Carbamatos atravessam a BHE; organofosforados não atravessam", "Ambos são quaternários, diferindo apenas na via de administração", "Carbamatos envelhecem a enzima; organofosforados não"], "gabarito": "B", "justificativa": "Carbamatos sofrem hidrólise lenta; organofosforados fosforilam de modo estável e envelhecem a enzima (Aula 4, slide 50).", "tecnica": "Classes de inibidores", "slide": 50, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um farmacêutico lê que a nicotina tem ação bifásica nos gânglios. O que significa esse padrão, segundo a aula?", "alternativas": ["Primeiro bloqueia e depois estimula os gânglios, com dupla função", "Estimula apenas o SNC, sem efeito sobre os gânglios", "Bloqueia os receptores muscarínicos sem efeito nicotínico", "Estimula apenas o coração, sem ação ganglionar", "Primeiro estimula e depois bloqueia os gânglios autonômicos"], "gabarito": "E", "justificativa": "A nicotina é bifásica: estimula e depois bloqueia gânglios (Aula 4, slide 40).", "tecnica": "Nicotina", "slide": 40, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "A metacolina é usada em teste de broncoprovocação. Qual receptor predomina nela e por que ela é útil no diagnóstico de asma, segundo a tabela da aula?", "alternativas": ["Nicotínico NM, com resposta rápida na placa motora", "Adrenérgico beta-2, com broncodilatação imediata", "Dopaminérgico D1, com vasodilatação brônquica", "Serotoninérgico 5-HT3, com resposta de náusea", "Muscarínico, com broncoconstrição lenta"], "gabarito": "E", "justificativa": "Metacolina tem predomínio M e é hidrolisada lentamente pela AChE, usada no teste de broncoprovocação (Aula 4, slide 29).", "tecnica": "Ésteres de colina", "slide": 29, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um agricultor exposto a agrotóxico tem sudorese, sialorreia, pupilas puntiformes e broncorreia. Qual é o diagnóstico sindrômico e o exame que confirma, segundo a aula?", "alternativas": ["Síndrome anticolinérgica, confirmada por atropina sérica", "Síndrome simpatomimética, confirmada por catecolaminas urinárias", "Síndrome serotoninérgica, confirmada por 5-HIAA urinário", "Reação alérgica, confirmada por IgE sérica total", "Síndrome colinérgica, por colinesterase"], "gabarito": "E", "justificativa": "A síndrome colinérgica aguda é confirmada por colinesterase, e a atropina é titulada pela secagem brônquica (Aula 4, slides 54 a 57).", "tecnica": "Intoxicação colinérgica", "slide": 57, "pdf": "pdf/gilmar/aula-04.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um agricultor intoxicado por organofosforado tem fraqueza proximal, de pares cranianos e respiratória 48 horas após a crise. Qual quadro a aula descreve, e em qual janela de tempo?", "alternativas": ["Síndrome intermediária, de 24 a 96 horas após a crise", "Crise colinérgica aguda, no primeiro minuto da exposição", "Neuropatia tardia, de 1 a 3 semanas após a exposição", "Anafilaxia, em menos de 30 minutos após a exposição", "Síndrome anticolinérgica, em menos de 2 horas após a exposição"], "gabarito": "A", "justificativa": "A síndrome intermediária ocorre de 24 a 96 horas após a crise, com fraqueza proximal, de pares cranianos e respiratória (Aula 4, slide 56).", "tecnica": "Síndrome intermediária", "slide": 56, "pdf": "pdf/gilmar/aula-04.pdf"}], "id": "farma-gilmar-04", "titulo": "Aula 4", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-05"] = {"subtitulo": "Adrenérgicos e antiadrenérgicos: agonistas, bloqueadores e receptores", "pdf": "pdf/gilmar/aula-05.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 5 · Adrenérgicos e Antiadrenérgicos (Prof. Dr. Gilmar S. Erzinger)", "Brunton, Chabner e Knollmann (Goodman & Gilman, 12ª ed.); Aula 07 de Farmacologia Veterinária (citados nos slides)"], "tabela": {"titulo": "Efeitos dos agonistas por órgão (slide 29)", "colunas": ["Órgão / tecido", "Receptor", "Efeito da estimulação"], "linhas": [["Coração (nós SA/AV, miocárdio)", "β1", "↑ automatismo, ↑ condução, ↑ contratilidade"], ["Músculo liso vascular", "α1 / β2", "Vasoconstrição (α1); vasodilatação no músculo esquelético (β2)"], ["Brônquios", "β2", "Broncodilatação"], ["Trato gastrintestinal", "α2 / β2", "↓ motilidade; contração dos esfíncteres"], ["Bexiga", "β2-3 / α1", "Relaxa o detrusor; contrai o esfíncter (retenção)"], ["Rim", "β1", "↑ liberação de renina"], ["Fígado e músculo esquelético", "β2 / α1", "Glicogenólise, gliconeogênese, captação de K⁺, tremor"], ["Tecido adiposo", "β3", "Lipólise"], ["Útero", "β2", "Relaxamento (varia com espécie e fase gestacional)"], ["Olho (músculo radial da íris)", "α1", "Midríase"]]}, "resumo": [{"titulo": "1. Bases: sistema simpático e receptores", "pontos": [{"t": "Simpático", "sub": ["Agonistas imitam a estimulação simpática (luta ou fuga) (slide 4).", "Via: fibra pré-ganglionar libera ACh em NN; pós-ganglionar libera NA no órgão; a medula adrenal lança adrenalina e NA no sangue (slide 5)."]}, {"t": "Síntese, liberação e recaptação da NA", "sub": ["Tirosina → DOPA → dopamina → NA; dopamina entra na vesícula pelo VMAT e vira NA (alvo da reserpina) (slide 6).", "Liberação por influxo de Ca²⁺; NA age nos receptores pós e pré-sinápticos (α2); recaptação pelo NET (alvo da cocaína); metabolismo por MAO e COMT (slide 6)."]}, {"t": "Receptores e vias", "sub": ["α1: Gq, PLC, IP3 e DAG, ↑Ca²⁺ (prazosina bloqueia). α2: Gi, ↓AMPc (ioimbina). β1, β2, β3: Gs, ↑AMPc, com PKA. D1: Gs (slides 7, 8, 10 e 12).", "Afinidades: α1 NA ≥ A; α2 A > NA; β1 NA = A; β2 A > NA; β3 NA = A (slide 7)."]}]}, {"titulo": "2. Modos de ação", "pontos": [{"t": "Direta, indireta e mista", "sub": ["Direta: ativa o receptor (adrenalina, fenilefrina, dobutamina). Indireta: aumenta liberação ou permanência de NA (anfetamina, cocaína, inibidores da MAO e COMT). Mista: as duas coisas (efedrina) (slide 17).", "Respostas indiretas desaparecem após depleção da NA com reserpina (slide 17)."]}, {"t": "Catecolaminas × não catecólicas", "sub": ["Catecolaminas (adrenalina, NA, dopamina, dobutamina, isoproterenol): polares, IV, ação curta, degradadas por MAO e COMT (slide 16).", "Não catecólicas (fenilefrina, efedrina, salbutamol, terbutalina): VO ou inalatória, ação mais longa; algumas atravessam a BHE (slide 16)."]}]}, {"titulo": "3. Principais agonistas", "pontos": [{"t": "Adrenalina", "sub": ["Efeitos: inotrópica e cronotrópica positiva (β1), vasoconstrição (α1), vasodilatação muscular (β2), broncodilatação (β2), ↑ glicose e lactato (slide 21).", "Usos: anafilaxia (escolha), parada cardiorrespiratória, prolongamento de anestésicos locais, hemostasia tópica (slide 21).", "Adversos: taquicardia, arritmia, fibrilação ventricular, isquemia miocárdica (slide 21)."]}, {"t": "Noradrenalina e isoproterenol", "sub": ["NA: vasoconstrição intensa (↑ PAS e PAD), bradicardia reflexa; uso no choque vasodilatador após reposição volêmica; extravasamento causa necrose (slide 22).", "Isoproterenol: β não seletivo; taquicardia, vasodilatação (↓ PAS diastólica); bradicardia severa e bloqueio AV (slide 22)."]}, {"t": "Dopamina por dose", "sub": ["Baixa (D1, < 2 µg/kg/min): vasodilatação renal, natriurese. Intermediária (β1, 2 a 10): inotropismo. Alta (α1, > 10): vasoconstrição (slide 24)."]}, {"t": "Dobutamina", "sub": ["β1; 2,5 a 10 µg/kg/min; choque cardiogênico e séptico; ICC descompensada; tolerância em infusões prolongadas; ineficaz após betabloqueio (slide 25)."]}, {"t": "β2 e α1 em clínica", "sub": ["β2: salbutamol, terbutalina, salmeterol, formoterol e clembuterol; asma, DPOC e tocólise; tremor e taquicardia como adversos (slide 26).", "α1: fenilefrina (vasoconstrição sem efeito cardíaco direto, não é catabolizada pela COMT); imidazolinas tópicas (nafazolina, oximetazolina) com risco de congestão de rebote (slide 27)."]}, {"t": "α2 centrais", "sub": ["Clonidina e metildopa (hipertensão humana); xilazina, detomidina, medetomidina e dexmedetomidina na veterinária: sedação, analgesia e bradicardia (slide 28)."]}]}, {"titulo": "4. Efeitos por órgão", "pontos": [{"t": "Tabela-resumo", "sub": ["Coração: β1 (automatismo, condução, contratilidade). Músculo liso vascular: α1 vasoconstrição; β2 vasodilatação muscular. Brônquios: β2. TGI: α2 e β2. Bexiga: β2-3 relaxa detrusor; α1 contrai esfíncter (retenção). Rim: β1, renina. Fígado e músculo: β2 e α1. Tecido adiposo: β3, lipólise. Útero: β2. Íris: α1, midríase (slide 29; ver a tabela da aula)."]}]}, {"titulo": "5. Antagonistas", "pontos": [{"t": "Alfabloqueadores", "sub": ["α não seletivos: fenoxibenzamina (irreversível, exceção) e fentolamina. α1 seletivos: prazosina, terazosina, doxazosina, tansulosina. α2: atipamezol, ioimbina, tolazolina (slide 37).", "Efeitos: ↓ resistência periférica, taquicardia reflexa e hipotensão postural; após α-bloqueio, adrenalina baixa a PA (slide 40).", "Usos: feocromocitoma, vasoespasmo, hiperplasia prostática (tansulosina) (slide 40)."]}, {"t": "Antagonistas α2 (reversão)", "sub": ["Atipamezol: reverte medetomidina e dexmedetomidina; ioimbina e tolazolina revertem xilazina (slide 41).", "A reversão também retira a analgesia; planejar analgesia antes (slide 41)."]}, {"t": "Betabloqueadores", "sub": ["Não seletivos (propranolol, nadolol, timolol, pindolol, sotalol); β1 seletivos (atenolol, metoprolol, esmolol, bisoprolol); de 3ª geração com vasodilatação (carvedilol e labetalol: α1; nebivolol: NO) (slides 37 e 42).", "Efeitos: ↓ FC, contratilidade e renina; sem hipotensão postural. Cuidados: asma (preferir β1), ICC descompensada, bradicardia, mascaram hipoglicemia; não suspender abruptamente (slide 42).", "Glaucoma: timolol tópico reduz produção de humor aquoso (slide 49)."]}, {"t": "Reserpina", "sub": ["Bloqueia o VMAT; NA, dopamina e serotonina são degradadas pela MAO; efeito lento e longo; abole respostas a anfetamina (slide 50)."]}]}, {"titulo": "6. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Receptor define o efeito (α1 contrai, β1 acelera, β2 relaxa, α2 inibe NA).", "Dopamina por faixa de dose.", "Betabloqueador em asmático e em diabético."]}]}], "glossario": [{"termo": "Gq / Gs / Gi", "tecnica": "Vias de sinalização", "definicao": "Proteínas G que ativam fosfolipase C (Gq), ativam adenilil ciclase (Gs) ou inibem a adenilil ciclase (Gi).", "slide": 10}, {"termo": "Dopamina em dose baixa (D1)", "tecnica": "Dose-dependência", "definicao": "Vasodilatação renal, mesentérica e coronária, com aumento de fluxo e natriurese.", "slide": 24}, {"termo": "Catecolaminas", "tecnica": "Classificação", "definicao": "Adrenalina, noradrenalina, dopamina, dobutamina e isoproterenol; polares, de ação rápida e curta.", "slide": 16}, {"termo": "Efedrina", "tecnica": "Ação mista", "definicao": "Libera NA, inibe sua recaptação e ativa α e β diretamente em doses altas; não é catecol.", "slide": 18}, {"termo": "NET", "tecnica": "Recaptação", "definicao": "Transportador de noradrenalina; alvo da cocaína, que mantém a NA na fenda.", "slide": 18}, {"termo": "VMAT", "tecnica": "Armazenamento", "definicao": "Transportador vesicular; alvo da reserpina, que deixa a NA no citoplasma.", "slide": 50}], "caso": {"titulo": "Caso: anafilaxia em paciente asmático com betabloqueador", "perfil": "Escolha do fármaco e efeitos de betabloqueio.", "etapas": [{"titulo": "Etapa 1: anafilaxia", "texto": "Homem de 35 anos tem anafilaxia após picada de inseto: hipotensão, edema de laringe e broncoespasmo. Chega ao pronto-socorro com pressão de 70 por 40 mmHg.", "perguntas": [{"pergunta": "Qual é o fármaco de escolha, segundo a aula?", "alts": ["Adrenalina, pelos efeitos α1, β1 e β2", "Propranolol, para reduzir a frequência cardíaca", "Dobutamina, pelo efeito inotrópico apenas", "Fenoxibenzamina, pelo bloqueio alfa irreversível", "Clonidina, pela ação central sedativa"], "erradas": ["Propranolol bloqueia β e pioraria o broncoespasmo e a hipotensão.", "Dobutamina atua em β1 e não resolve o broncoespasmo nem a vasoconstrição.", "Fenoxibenzamina bloqueia α e reduziria a pressão, o oposto do necessário.", "Clonidina causa sedação e hipotensão, sem indicação na anafilaxia."], "justificativa": "A adrenalina é o fármaco de escolha na anafilaxia, por efeitos α1, β1 e β2 (slide 21)."}]}, {"titulo": "Etapa 2: asmático em betabloqueador", "texto": "Outro paciente, asmático, usa propranolol para hipertensão. Tem broncoespasmo e precisa de broncodilatação.", "perguntas": [{"pergunta": "Por que o propranolol agrava o quadro, e qual classe de betabloqueador é preferível?", "alts": ["Bloqueia β2 brônquico; preferir β1-seletivos, que poupam os brônquios", "Ativa α1 brônquico; preferir α2-seletivos, sem efeito pulmonar", "Induz tolerância β2; preferir dopamina em dose baixa", "Libera histamina; preferir anti-histamínicos de primeira geração", "Inibe COX-2 brônquica; preferir coxibes"], "erradas": ["Propranolol não ativa α1 no brônquio; o problema é o bloqueio de β2.", "Dopamina em dose baixa atua em D1 renal e não é a escolha para broncoespasmo.", "A histamina não é o mecanismo do efeito do propranolol.", "Coxibes são anti-inflamatórios e não tratam o broncoespasmo beta."], "justificativa": "Betabloqueadores não seletivos causam broncoconstrição; β1-seletivos poupam os brônquios (slides 42 e 44)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um agonista de receptor α1 é administrado. Qual é a via de sinalização e o efeito celular descritos na aula?", "alternativas": ["Gs, com ativação da adenilil ciclase e aumento de AMPc", "Gi, com inibição da adenilil ciclase e queda de AMPc", "Canal iônico de sódio, com despolarização rápida", "Receptor tirosina-quinase, com fosforilação de proteínas", "Gq, com fosfolipase C e cálcio"], "gabarito": "E", "justificativa": "α1 usa Gq, ativa a fosfolipase C e aumenta IP3, DAG e cálcio (Aula 5, slides 7 e 10).", "tecnica": "Receptores adrenérgicos", "slide": 10, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um paciente com taquicardia recebe um agonista β1 em dose terapêutica. Qual é o efeito esperado no coração, segundo a tabela da aula?", "alternativas": ["Redução do automatismo e da contratilidade, com bradicardia", "Aumento do automatismo, da condução e da contratilidade", "Aumento da resistência periférica, sem efeito sobre o ritmo", "Redução da condução, com bloqueio atrioventricular obrigatório", "Aumento da secreção de muco no nó sinusal"], "gabarito": "B", "justificativa": "A estimulação β1 aumenta automatismo, condução e contratilidade (Aula 5, slide 29).", "tecnica": "Efeitos por órgão", "slide": 29, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um agonista α2 de ação central é usado em contenção química. Qual efeito central e qual efeito periférico são esperados, segundo a aula?", "alternativas": ["Euforia e taquicardia; hipertensão por aumento do tônus simpático", "Broncodilatação e lipólise; hipotensão por vasodilatação", "Sedação, analgesia e bradicardia", "Vasoconstrição intensa e midríase; taquicardia reflexa", "Aumento da motilidade intestinal; diarreia e hipotensão"], "gabarito": "C", "justificativa": "α2 central causa sedação, analgesia e relaxamento; reduz o tônus simpático, com bradicardia e hipotensão (Aula 5, slide 28).", "tecnica": "Agonistas α2", "slide": 28, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Uma dopamina é infundida em dose superior a 10 µg/kg/min. Qual é o efeito predominante e o que se perde, segundo a aula?", "alternativas": ["Vasodilatação D1 renal, com natriurese intensa", "Inotropismo β1 puro, sem efeito vascular", "Broncodilatação β2 com taquicardia", "Vasoconstrição α1 e perda renal", "Efeito opioide central, com sedação"], "gabarito": "D", "justificativa": "Acima de 10 µg/kg/min, a dopamina age em α1 e perde o efeito renal (Aula 5, slide 24).", "tecnica": "Dopamina por dose", "slide": 24, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Uma dopamina é infundida em dose de 1 µg/kg/min. Qual receptor predomina e qual efeito renal é esperado, segundo a aula?", "alternativas": ["α1, com vasoconstrição renal intensa", "D1, com vasodilatação renal", "β1, com aumento de contratilidade renal", "β2, com broncodilatação renal", "α2, com sedação e redução da filtração glomerular"], "gabarito": "B", "justificativa": "Em dose baixa (< 2 µg/kg/min), a dopamina age em D1 e causa vasodilatação renal e natriurese (Aula 5, slide 24).", "tecnica": "Dopamina em dose baixa", "slide": 24, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente com fenilefrina tem bradicardia reflexa. Qual mecanismo explica isso, segundo a aula?", "alternativas": ["A fenilefrina bloqueia β1 cardíaco, reduzindo o automatismo", "A fenilefrina libera acetilcolina, que age no nó sinusal", "Vasoconstrição eleva pressão; reflexo reduz FC", "A fenilefrina inibe a COMT, acumulando adenosina no coração", "A fenilefrina causa hemólise, com anemia reflexa"], "gabarito": "C", "justificativa": "A vasoconstrição aumenta a pressão, e o barorreflexo reduz a frequência (Aula 5, slide 27).", "tecnica": "Agonistas α1", "slide": 27, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um paciente com anafilaxia recebe adrenalina. Quais receptores são estimulados e qual efeito pulmonar é desejado, segundo a aula?", "alternativas": ["Apenas α2; broncoconstrição por contração muscular", "α1, β1 e β2; broncodilatação por β2", "Apenas β3; lipólise sem efeito pulmonar", "Apenas D1; vasodilatação pulmonar", "Apenas M3; secreção brônquica"], "gabarito": "B", "justificativa": "A adrenalina age em α1, β1 e β2; é broncodilatadora por β2 (Aula 5, slide 21).", "tecnica": "Adrenalina", "slide": 21, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Uma efedrina é administrada oralmente. Qual é o mecanismo de ação e por que ela é diferente da adrenalina?", "alternativas": ["Ativa diretamente α e β como a adrenalina, sem efeito indireto", "Bloqueia a MAO, como os inibidores da MAO, sem liberar NA", "Inibe a adenilil ciclase, o que é a ação dos receptores α2", "Atua apenas em receptores M3, como a acetilcolina", "Libera NA e inibe recaptação"], "gabarito": "E", "justificativa": "A efedrina é mista: libera NA e inibe a recaptação; não é catecol, e por isso é oral e de ação mais longa (Aula 5, slides 16 e 18).", "tecnica": "Ação mista", "slide": 18, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "A cocaína potencializa a resposta simpática. Qual transportador é bloqueado, e qual é o efeito sobre a NA na fenda?", "alternativas": ["NET, com NA mais tempo na fenda", "VMAT, com a NA retida no citoplasma", "COMT, com a NA degradada mais rapidamente", "MAO, com a NA convertida em dopamina", "VAChT, com a ACh retida na vesícula"], "gabarito": "A", "justificativa": "A cocaína bloqueia o NET; a NA permanece na fenda e potencializa a resposta (Aula 5, slide 18).", "tecnica": "Inibidor de recaptação", "slide": 18, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "A reserpina é usada em um paciente que depois recebe anfetamina sem resposta. Qual é o mecanismo da reserpina, segundo a aula?", "alternativas": ["Bloqueia o VMAT, depletando aminas", "Ativa receptores α2, que inibem a liberação de NA", "Aumenta a recaptação pelo NET, reduzindo a NA disponível", "Bloqueia receptores β, impedindo a resposta simpática", "Inibe a dopamina-β-hidroxilase, aumentando a síntese de NA"], "gabarito": "A", "justificativa": "A reserpina bloqueia o VMAT e depleta aminas; isso abole respostas indiretas, como as da anfetamina (Aula 5, slide 50).", "tecnica": "Reserpina", "slide": 50, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um paciente recebe um α-bloqueador e depois adrenalina, e a pressão cai. Por que a adrenalina passa a baixar a pressão, segundo a aula?", "alternativas": ["Sem α, a adrenalina age em α2 e aumenta a resistência periférica", "Sem α, a adrenalina é degradada pela COMT no sangue", "Sem α, adrenalina age em β2 (vasodilatação)", "Sem α, a adrenalina ativa apenas receptores muscarínicos", "Sem α, a adrenalina não tem efeito e a pressão cai por outras causas"], "gabarito": "C", "justificativa": "Após α-bloqueio, a adrenalina age em β2 e causa vasodilatação, reduzindo a PA (Aula 5, slide 40).", "tecnica": "Alfabloqueadores", "slide": 40, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um asmático em uso de propranolol tem broncoespasmo. Qual receptor está bloqueado e qual classe seria preferível, segundo a aula?", "alternativas": ["α1, com preferência por α2-seletivos, que não afetam o pulmão", "β1, com preferência por não seletivos, que fortalecem os brônquios", "M3, com preferência por anticolinérgicos de primeira geração", "β2, com preferência por β1-seletivos, que poupam os brônquios", "D1, com preferência por dopamina em dose alta"], "gabarito": "D", "justificativa": "Betabloqueadores não seletivos bloqueiam β2 e causam broncoconstrição; β1-seletivos poupam os brônquios (Aula 5, slides 42 e 44).", "tecnica": "Betabloqueadores em asma", "slide": 42, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um diabético em uso de betabloqueador apresenta hipoglicemia sem taquicardia e sem tremor. Qual é a explicação, segundo a aula?", "alternativas": ["Mascara sinais adrenérgicos de alerta", "O betabloqueio aumenta a secreção de insulina pelo pâncreas", "O betabloqueio ativa α2, que reduz a glicemia", "O betabloqueio inibe a gliconeogênese hepática de forma irreversível", "O betabloqueio aumenta a excreção renal de glicose"], "gabarito": "A", "justificativa": "A aula cita que betabloqueadores mascaram sinais de hipoglicemia em diabéticos (Aula 5, slide 42).", "tecnica": "Betabloqueadores em diabetes", "slide": 42, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Qual é a diferença entre carvedilol e atenolol quanto ao receptor α1, segundo a aula?", "alternativas": ["Ambos são α1-seletivos, sem efeito sobre os receptores β", "Atenolol bloqueia α1; carvedilol é β1-seletivo puro", "Ambos bloqueiam α2, sem efeito sobre α1 ou β", "Carvedilol ativa α1; atenolol bloqueia α1 de forma irreversível", "Carvedilol bloqueia α1 além do β"], "gabarito": "E", "justificativa": "Carvedilol e labetalol têm bloqueio α1 adicional; atenolol é β1-seletivo (Aula 5, slides 37 e 48).", "tecnica": "Betabloqueadores de 3ª geração", "slide": 48, "pdf": "pdf/gilmar/aula-05.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um paciente recebe noradrenalina em choque vasodilatador e tem redução do fluxo renal. Qual mecanismo a aula descreve, e por que o extravasamento é perigoso?", "alternativas": ["Ativação β2 renal; o extravasamento causa edema alérgico", "Bloqueio D1 renal; o extravasamento causa hipotensão", "Ativação M3 renal; o extravasamento causa broncorreia", "Vasoconstrição α1 intensa; o extravasamento causa necrose local", "Inibição COMT renal; o extravasamento causa acúmulo de dopamina"], "gabarito": "D", "justificativa": "A NA causa vasoconstrição renal intensa; o extravasamento causa necrose (Aula 5, slide 22).", "tecnica": "Noradrenalina", "slide": 22, "pdf": "pdf/gilmar/aula-05.pdf"}], "id": "farma-gilmar-05", "titulo": "Aula 5", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-06"] = {"subtitulo": "Autacoides: histamina, serotonina, eicosanoides, PAF, cininas e AINEs", "pdf": "pdf/gilmar/aula-06.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 6 · Autacoides (Prof. Gilmar S. Erzinger)", "Brunton, Chabner e Knollmann (Goodman & Gilman); Nature Reviews Drug Discovery (citados nos slides)"], "tabela": {"titulo": "Prostanoides: produção e ação (slide 33)", "colunas": ["Sigla", "Prostanoide", "Produção", "Ação"], "linhas": [["PGD2", "Prostaglandina D2", "Mastócitos", "Vasodilatação, inibição da agregação plaquetária, relaxamento do TGI e útero"], ["PGF2α", "Prostaglandina F2α", "Miométrio", "Contração do miométrio, luteólise e broncoconstrição"], ["PGI2", "Prostaciclina", "Endotélio", "Vasodilatação, hiperalgesia, inibição da agregação, renina e natriurese"], ["PGE2", "Prostaglandina E2", "Pulmão, macrófago", "Vasodilatação, hiperalgesia, febre, proliferação celular"], ["TXA2", "Tromboxano A2", "Plaquetas", "Agregação plaquetária, vasoconstrição e broncoconstrição"]]}, "resumo": [{"titulo": "1. Inflamação e sinais cardinais", "pontos": [{"t": "Definição", "sub": ["Reação a infecção ou lesão de tecidos, essencial à sobrevivência; pode ser exagerada e persistente (slide 3).", "Sinais cardinais: calor, rubor, edema (tumor), dor e perda de função (slide 3)."]}, {"t": "Resposta imune inata e dor", "sub": ["Mediadores (histamina, prostaglandinas, bradicinina, serotonina e citocinas) sensibilizam terminais nociceptivos (slides 4 e 5).", "Exemplo do slide 50: bradicinina sozinha não aumenta o sinal; após PGE2, aumenta (sinergia)."]}]}, {"titulo": "2. Autacoides", "pontos": [{"t": "Conceito", "sub": ["Substâncias naturais, rapidamente produzidas em resposta a estímulos, com ação local (slide 6).", "Grupos: histamina, serotonina, eicosanoides e PAF (lipídios), peptídeos (cininas, neuropeptídeos) e citocinas (slide 6)."]}]}, {"titulo": "3. Histamina", "pontos": [{"t": "Ações por receptor", "sub": ["H1 (Gq): broncoconstrição, dilatação de vênulas, contração endotelial (edema e pápula), sensibilização de nervos (prurido e dor) (slides 9 e 10).", "H2 (Gs): aumenta secreção de ácido gástrico; ação cardíaca leve (slide 9).", "H3 (Gi/o): neurotransmissor no SNC (slide 9). H4 (Gi/o): células hematopoiéticas (slide 10)."]}, {"t": "Anti-histamínicos", "sub": ["H1 de primeira geração (lipofílicos): sedação central. Segunda geração: menos sedação, igual eficácia contra alergia (slides 13 e 15).", "Não funcionam contra vasculite urticariforme nem angioedema hereditário (slide 15).", "Antagonistas H2 (cimetidina, ranitidina): doença do refluxo e úlcera péptica (slide 16).", "Estabilizadores de mastócitos (cromolin, nedocromil) e antagonismo fisiológico com adrenalina na anafilaxia (slides 11 e 12)."]}]}, {"titulo": "4. Serotonina", "pontos": [{"t": "Síntese e distribuição", "sub": ["Produzida do triptofano (triptofano hidroxilase, depois dopa-descarboxilase); degradada pela MAO a 5-HIAA (slide 19).", "Mais de 90% no intestino (enterocromafins); plaquetas armazenam e liberam na agregação; SNC em áreas do mesencéfalo (slide 20)."]}, {"t": "Receptores e efeitos", "sub": ["5-HT1A, 1B, 1D, 1E e 1F: inibem a adenilato ciclase (slide 21).", "5-HT2A, 2B, 2C: ativam fosfolipase C; 5-HT3: canal iônico; 5-HT4 a 5-HT7: ativam AC (slide 22).", "Efeitos: motilidade intestinal, contração de brônquios e útero, vasoconstrição e vasodilatação, agregação plaquetária, sensibilização nociceptiva (slide 23)."]}, {"t": "Fármacos", "sub": ["Triptanos (sumatriptano e outros): agonistas 5-HT1B/1D; vasoconstrição de vasos cerebrais e meníngeos na enxaqueca (slide 24).", "Ondansetrona: antagonista 5-HT3 da zona de gatilho, para quimioterapia e pós-operatório (slide 25).", "Tegaserode e prucaloprida: agonistas parciais 5-HT4 para constipação e síndrome do intestino irritável (slide 25)."]}]}, {"titulo": "5. Eicosanoides", "pontos": [{"t": "Origem", "sub": ["Derivados do ácido araquidônico (20 carbonos) liberado de fosfolipídeos pela PLA2 (slides 27 e 28).", "Via da COX: prostaglandinas e tromboxanos. Via da LOX: leucotrienos, HETE e lipoxinas (slide 29)."]}, {"t": "Isoformas da COX", "sub": ["COX-1 constitutiva: estômago (citoproteção por PGE2), plaquetas (TxA2), rim, útero (PGF2α) (slides 30 e 31).", "COX-2 induzida: macrófagos, linfócitos, endotélio, na dor e na inflamação (slides 30 e 31)."]}, {"t": "Prostanoides", "sub": ["PGD2: vasodilatação e inibição da agregação. PGF2α: contração do miométrio e luteólise. PGI2: vasodilatação e antiagregação. PGE2: vasodilatação, hiperalgesia e febre. TXA2: agregação e broncoconstrição (slide 33)."]}]}, {"titulo": "6. PAF e cininas", "pontos": [{"t": "PAF", "sub": ["Fosfolipídeo mediador: aumenta adesão celular e ativa endotélio; 100 a 1.000 vezes mais potente que a histamina (slides 35 e 36)."]}, {"t": "Cininas", "sub": ["Bradicinina e calidina formadas por calicreínas a partir de cininogênios (slide 38).", "B2 (constitutivo; antagonista Hoe 140) e B1 (induzível; Des-Arg-Hoe 140) (slide 39).", "Vasodilatação dependente de NO, aumento da permeabilidade de vênulas, sensibilização de nociceptores (slide 39)."]}]}, {"titulo": "7. Citocinas", "pontos": [{"t": "Classes", "sub": ["Interleucinas (IL-1, IL-6, IL-8, IL-10, IL-13); fatores de crescimento (GM-CSF, M-CSF); quimiocinas (CC, CXC, XC, CX3C); interferons (IFN-alfa, beta, gama); pró-inflamatórias TNF-alfa (slide 42).", "Podem ser pró ou anti-inflamatórias (slide 43)."]}]}, {"titulo": "8. AINEs", "pontos": [{"t": "Mecanismo e efeitos", "sub": ["Inibem COX e reduzem PGE2 e prostaciclina: anti-inflamatório, analgésico e antipirético (slide 58).", "Antipirético: IL-1 eleva prostaglandinas no hipotálamo; AINEs reduzem PGE2 no SNC (slide 58)."]}, {"t": "Fármacos", "sub": ["Aspirina: inativação irreversível da COX-1 e COX-2 por acetilação; antiagregante; 75% metabolizada no fígado; meia-vida de 4 h (slide 60).", "Paracetamol: analgésico e antipirético forte, pouco anti-inflamatório; efeito central pela COX-3; hepatotoxicidade em doses altas (slide 61).", "Propiônicos (ibuprofeno e outros): dor, inflamação e dismenorreia (slide 62).", "Oxicans (piroxicam, meloxicam): meloxicam com leve preferência por COX-2 (10:1) em baixas doses (slide 63).", "Coxibes (celecoxibe, rofecoxibe): seletivos COX-2, menos efeito gástrico, risco cardiovascular (slides 64 e 65)."]}, {"t": "Efeitos adversos", "sub": ["TGI: inibição da COX-1, dispepsia, úlcera, hemorragia (slide 67).", "Renal: PGE2 e PGI2 vasodilatadoras; insuficiência reversível e nefropatia por analgésicos (slide 68).", "Cardiovascular: hipertensão, AVC e infarto com uso prolongado, sobretudo com coxibes (slide 69).", "Outros: reações cutâneas, broncoespasmo em asmáticos sensíveis à aspirina, distúrbios hepáticos e depressão da medula (slide 70)."]}]}, {"titulo": "9. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Qual receptor H1, H2 e 5-HT faz o quê.", "COX-1 × COX-2: o que cada uma produz e por que o coxibe tem risco trombótico.", "Efeito gástrico, renal e cardiovascular dos AINEs."]}]}], "glossario": [{"termo": "Autacoide", "tecnica": "Conceito", "definicao": "Substância natural produzida rapidamente em resposta a estímulos, com ação local.", "slide": 6}, {"termo": "PAF", "tecnica": "Mediador lipídico", "definicao": "Fator ativador plaquetário, mediador fosfolipídico que aumenta a adesão celular, 100 a 1.000 vezes mais potente que a histamina.", "slide": 36}, {"termo": "COX-1 e COX-2", "tecnica": "Cicloxigenases", "definicao": "COX-1 constitutiva (estômago, plaquetas, rim); COX-2 induzida na inflamação; alvo dos AINEs.", "slide": 30}, {"termo": "Coxibes", "tecnica": "AINE seletivo", "definicao": "Inibidores seletivos da COX-2, como celecoxibe e rofecoxibe, com menos efeito gástrico.", "slide": 64}, {"termo": "Nefropatia associada a analgésicos", "tecnica": "Efeito renal", "definicao": "Lesão renal por uso contínuo de altas doses de AINEs, frequentemente irreversível.", "slide": 68}, {"termo": "5-HT3", "tecnica": "Receptor da serotonina", "definicao": "Canal iônico da zona de gatilho; alvo da ondansetrona contra náuseas.", "slide": 22}], "caso": {"titulo": "Caso: asmático sensível à aspirina com dor", "perfil": "Broncoespasmo por AINE e risco de sangramento por COX-1.", "etapas": [{"titulo": "Etapa 1: broncoespasmo após AINE", "texto": "Mulher de 40 anos, asmática, toma ácido acetilsalicílico para cefaleia e evolui com broncoespasmo e sibilos minutos depois.", "perguntas": [{"pergunta": "Qual é o mecanismo mais provável do broncoespasmo, segundo a aula?", "alts": ["Inibição da COX com desvio do ácido araquidônico para leucotrienos broncoconstritores", "Ativação de receptores H2 brônquicos pela histamina liberada", "Bloqueio de receptores beta-2 pelo ácido acetilsalicílico", "Ativação de receptores 5-HT3 pulmonares pela serotonina", "Inibição da COX-2, que aumenta a produção de PGE2 brônquica"], "erradas": ["Receptores H2 não são o mecanismo do broncoespasmo descrito.", "O ácido acetilsalicílico não atua como bloqueador beta-2.", "Receptores 5-HT3 não são o mecanismo citado para a asma por AINE.", "Inibir COX-2 reduz prostaglandinas, e não aumenta PGE2."], "justificativa": "A aula cita broncoespasmo em asmáticos sensíveis à aspirina entre os efeitos dos AINEs (slide 70). O desvio para leucotrienos é um mecanismo comum da via da lipoxigenase (slide 29)."}]}, {"titulo": "Etapa 2: sangramento em idoso", "texto": "Homem de 72 anos, usando AINE não seletivo por artrose, tem melena e queda de hemoglobina. A endoscopia mostra úlcera gástrica.", "perguntas": [{"pergunta": "Qual é o mecanismo do sangramento, segundo a aula?", "alts": ["Inibição da COX-1, com perda de prostaglandinas gastroprotetoras", "Inibição da COX-2, com excesso de tromboxano na mucosa", "Ativação da histamina H1, com aumento da secreção gástrica", "Bloqueio dos receptores 5-HT4, com redução da motilidade", "Estímulo de PAF, com vasodilatação da submucosa"], "erradas": ["A inibição da COX-2 não é o mecanismo gastrointestinal central, segundo a aula.", "Excesso de tromboxano não é o mecanismo descrito para a úlcera.", "Histamina H1 não é o mecanismo de sangramento pelo AINE.", "Receptores 5-HT4 estimulam a motilidade, e não causam a lesão descrita."], "justificativa": "Os efeitos indesejados no TGI são principalmente pela inibição da COX-1 constitutiva, que suprime as prostaglandinas gastroprotetoras (slide 67)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um paciente com dor após lesão tecidual tem bradicinina e prostaglandina. Por que a sensação dolorosa aumenta quando as duas são aplicadas juntas, segundo a aula?", "alternativas": ["Sinergia: PGE2 sensibiliza, bradicinina amplifica", "A bradicinina bloqueia a PGE2, reduzindo a dor de forma aditiva", "A PGE2 é metabolizada pela bradicinina, produzindo histamina dolorosa", "Nenhuma sinergia existe; a dor depende apenas de citocinas de Th1", "As duas atuam apenas sobre o SNC, sem efeito periférico"], "gabarito": "A", "justificativa": "Em preparação de nervo, bradicinina sozinha não aumenta o sinal; após PGE2, aumenta (Aula 6, slide 50).", "tecnica": "Sinergia de mediadores", "slide": 50, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Uma pessoa tem reação brônquica após um anti-histamínico de primeira geração. Qual receptor é o alvo do fármaco e qual é o efeito esperado no receptor H1, segundo a aula?", "alternativas": ["H2, com bloqueio da secreção de ácido gástrico", "H3, com bloqueio de neurotransmissão no SNC", "H4, com bloqueio da diurese renal", "H1, que causa edema e pápula", "Nenhum receptor, pois o anti-histamínico age nas prostaglandinas"], "gabarito": "D", "justificativa": "Anti-histamínicos H1 bloqueiam a permeabilidade capilar que forma edema e pápula (Aula 6, slides 9, 14 e 15).", "tecnica": "Anti-histamínicos H1", "slide": 14, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um paciente com angioedema hereditário toma anti-histamínico H1 de segunda geração sem melhora. Qual é a explicação dada pela aula?", "alternativas": ["Anti-histamínicos H1 não agem no angioedema", "O paciente tem alergia tipo IV, que o anti-histamínico não trata", "A segunda geração é menos potente que a primeira para qualquer edema", "O paciente tem excesso de histamina, que o H1 aumenta", "O paciente tem deficiência de NK, que o H1 não modula"], "gabarito": "A", "justificativa": "A aula diz que H1 não são efetivos contra vasculite urticariforme nem angioedema hereditário (Aula 6, slide 15).", "tecnica": "Limites dos H1", "slide": 15, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um paciente tem refluxo e recebe ranitidina. Qual receptor é bloqueado, e qual efeito gástrico é reduzido, segundo a aula?", "alternativas": ["H1 nas células parietais, reduzindo a permeabilidade vascular", "H2 nas células parietais", "H3 no SNC, reduzindo o estado de vigília", "5-HT3 no intestino, reduzindo a motilidade", "COX-1 no estômago, reduzindo a PGE2"], "gabarito": "B", "justificativa": "Cimetidina e ranitidina são antagonistas H2, reduzindo a secreção gástrica (Aula 6, slide 16).", "tecnica": "Antagonistas H2", "slide": 16, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um paciente com enxaqueca recebe sumatriptano. Qual receptor é ativado e qual efeito vascular o fármaco produz nos vasos cerebrais, segundo a aula?", "alternativas": ["5-HT3, com vasodilatação de vasos meníngeos", "5-HT2A, com aumento da permeabilidade endotelial", "H1, com vasodilatação dos vasos cerebrais", "COX-2, com inibição da prostaglandina cerebral", "5-HT1B/1D, com vasoconstrição cerebral"], "gabarito": "E", "justificativa": "Os triptanos são agonistas 5-HT1B/1D, com vasoconstrição cerebral e meníngea (Aula 6, slide 24).", "tecnica": "Triptanos", "slide": 24, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente com constipação crônica recebe prucaloprida. Qual receptor é estimulado e qual é o efeito no intestino, segundo a aula?", "alternativas": ["5-HT3, reduzindo a motilidade intestinal", "5-HT1B, causando vasoconstrição intestinal", "5-HT4, aumentando a motilidade", "H2, reduzindo a secreção de muco", "COX-2, aumentando a prostaglandina intestinal"], "gabarito": "C", "justificativa": "Tegaserode e prucaloprida são agonistas parciais de 5-HT4, que estimulam a motilidade (Aula 6, slide 25).", "tecnica": "Serotonina e motilidade", "slide": 25, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um paciente tem náusea intensa após quimioterapia. Qual fármaco a aula cita, e qual receptor ele bloqueia na zona de gatilho?", "alternativas": ["Sumatriptano, bloqueando 5-HT1B", "Ranitidina, bloqueando H2", "Aspirina, bloqueando COX-1", "Prucaloprida, bloqueando 5-HT4", "Ondansetrona, bloqueando 5-HT3"], "gabarito": "E", "justificativa": "A ondansetrona bloqueia receptores 5-HT3 da zona de gatilho quimiorreceptora (Aula 6, slide 25).", "tecnica": "Ondansetrona", "slide": 25, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um paciente jovem recebe aspirina e tem broncoespasmo. Qual é a classe de sensibilidade descrita na aula, e qual mecanismo de inibição da COX a aspirina usa?", "alternativas": ["Asmáticos alérgicos a IgE, com inibição reversível e competitiva", "Inativação irreversível da COX por acetilação", "Pacientes com deficiência de IgA, com inibição da lipoxigenase", "Pacientes com DGC, com ativação da COX-2 pelo superóxido", "Pacientes com LAD, com inibição da COX-1 pela integrina"], "gabarito": "B", "justificativa": "A aula cita broncoespasmo em asmáticos sensíveis à aspirina; a aspirina inativa a COX de forma irreversível por acetilação (Aula 6, slides 60 e 70).", "tecnica": "Aspirina", "slide": 60, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um paciente com dor de cabeça toma paracetamol em dose terapêutica e tem pouca inflamação. Qual é o subtipo de COX atribuído ao efeito central, segundo a aula?", "alternativas": ["COX-1, de atuação no estômago", "COX-2, de atuação em macrófagos", "Lipoxigenase, de atuação em leucócitos", "COX-3, de atuação no SNC", "Fosfolipase A2, de atuação na membrana"], "gabarito": "D", "justificativa": "O perfil do paracetamol parece decorrer de atuação central em COX-3 (Aula 6, slide 61).", "tecnica": "Paracetamol", "slide": 61, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um idoso usa AINE não seletivo e tem hemorragia digestiva. Qual COX é inibida e qual proteção é perdida, segundo a aula?", "alternativas": ["COX-2, com perda da PGI2 que protege o endotélio", "COX-1, com perda de PGE2 gastroprotetora", "COX-1, com perda da PGF2α que protege o útero", "COX-2, com perda da PGD2 que protege os mastócitos", "COX-1, com perda do TXA2 que protege as plaquetas"], "gabarito": "B", "justificativa": "A COX-1 constitutiva produz PGE2 gastroprotetora; sua inibição causa efeito gástrico (Aula 6, slides 31 e 67).", "tecnica": "Efeitos gastrointestinais", "slide": 67, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um paciente com coxibe tem risco de trombose. Qual desequilíbrio a aula descreve para explicar isso?", "alternativas": ["Inibição da COX-1 deixa a COX-2 favorecer a hemólise", "Ativação da lipoxigenase aumenta a fibrinólise", "Inibição do PAF reduz a agregação plaquetária", "Ativação do complemento inibe a COX-1", "Inibe COX-2; COX-1 favorece agregação"], "gabarito": "E", "justificativa": "O uso de coxibes favorece a COX-1, levando à agregação plaquetária e formação de trombos (Aula 6, slide 69).", "tecnica": "Coxibes e trombose", "slide": 69, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Qual é a prostaglandina que, segundo a aula, contrai o miométrio e promove luteólise?", "alternativas": ["PGE2, vasodilatadora e pró-inflamatória", "PGI2", "PGD2", "PGF2α", "TXA2"], "gabarito": "D", "justificativa": "PGF2α causa contração do miométrio, luteólise e broncoconstrição (Aula 6, slide 33).", "tecnica": "Prostanoides", "slide": 33, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um laboratório compara a potência do PAF com a histamina. Qual relação a aula informa?", "alternativas": ["PAF: 100 a 1.000 vezes", "PAF é 10 vezes menos potente que a histamina", "PAF e histamina têm potência igual", "PAF é 2 vezes mais potente que a histamina", "PAF é 1.000 vezes menos potente que a histamina"], "gabarito": "A", "justificativa": "O PAF é de 100 a 1.000 vezes mais potente que a histamina (Aula 6, slide 36).", "tecnica": "PAF", "slide": 36, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Qual é a origem da bradicinina e da calidina, segundo a aula, e qual receptor é induzível?", "alternativas": ["Formadas por COX sobre ácido araquidônico; B2 é induzível", "Formadas por PLA2 sobre fosfolipídeos; B2 é induzível", "Calicreínas sobre cininogênios", "Formadas por MAO sobre serotonina; H1 é induzível", "Formadas por COMT sobre catecolaminas; H2 é induzível"], "gabarito": "C", "justificativa": "Bradicinina e calidina são formadas por calicreínas sobre cininogênios; o receptor B1 é induzível (Aula 6, slides 38 e 39).", "tecnica": "Cininas", "slide": 38, "pdf": "pdf/gilmar/aula-06.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Quais são os sinais cardinais da inflamação que a aula lista, e qual deles corresponde à perda de função?", "alternativas": ["Febre, tosse, dispneia, calafrio e fadiga", "Hipotensão, taquicardia, cianose e sudorese", "Calor, rubor, edema, dor e perda de função", "Rash, prurido, urticária, edema labial e broncoespasmo", "Leucocitose, linfopenia, aumento de IgE e eosinofilia"], "gabarito": "C", "justificativa": "Calor, rubor, edema, dor e perda de função são os sinais cardinais (Aula 6, slide 3).", "tecnica": "Sinais cardinais", "slide": 3, "pdf": "pdf/gilmar/aula-06.pdf"}], "id": "farma-gilmar-06", "titulo": "Aula 6", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
